(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["video"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-far-drive-frame-autoregressive-video-2026"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-1\">一 · 控制周期里的那一帧：闭环在线服务的真实压力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-2\">二 · 旧方案的主流做法：整段离线去噪加滑窗切片</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-3\">三 · 显存与带宽：全序列驻留把批并发锁死</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-4\">四 · 误差沿帧回灌：滑窗方案掩盖不了的闭环特有失败</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-5\">五 · 为什么非改不可：三个约束同时收紧</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-6\">六 · 控制周期里的硬时延：为什么整段去噪在闭环中先失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-7\">七 · 请求到达形态：控制节拍驱动的帧级泊松流</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-8\">八 · 并发与批大小：时延预算倒推的上界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-9\">九 · SLO 的定义：单帧时延而非吞吐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-10\">十 · 负载塑造方案：窗口与批的联合定标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-11\">十一 · 可核查的测量口径清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-12\">十二 · 负载与方案的耦合边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-13\">十三 · 从帧自回归的算子清单说起</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-14\">十四 · 四种格式在单帧路径上的分工</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-15\">十五 · 累加精度与误差如何在回灌链上放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-16\">十六 · Blackwell 特性如何改变单帧 kernel 的形状</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-17\">十七 · 把精度选择落到帧时延预算上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-18\">十八 · 工程判断：格式表要跟窗口与批一起定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-19\">十九 · 精度边界：少步蒸馏下的数值误差与 Blackwell 算子代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-20\">二十 · 显存账本的三本账：权重、激活、KV</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-21\">二十一 · 分页与块表：把 KV 从“连续大数组”改成“可拼装的页”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-22\">二十二 · 压缩与复用：KV 不是只能原样存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-23\">二十三 · 卸载与带宽：瓶颈到底在哪一层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-24\">二十四 · 可复算的显存预算：从窗口与并发反推档位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-25\">二十五 · 与批调度和 SLO 的耦合点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-26\">二十六 · 帧级到达流下的连续批处理：把“批”从请求改成节拍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-27\">二十七 · Chunked prefill 的等价物：首帧冷启动与窗口重算的分块</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-28\">二十八 · 优先级与抢占：谁先出帧，谁被降窗口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-29\">二十九 · 分离式预填/解码在帧自回归中的映射</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-30\">三十 · 尾延迟的压法：从批内最慢成员到窗口长度的方差</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-31\">三十一 · 切分维度：帧自回归把并行问题改写</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-32\">三十二 · All-Reduce 与 All-to-All：两种通信的不同代价曲线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-33\">三十三 · NIXL 传输：把 KV 缓存搬出计算路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-34\">三十四 · 通信何时成为瓶颈：三个判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-35\">三十五 · 与批调度、窗口长度的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-36\">三十六 · 并行切分与通信：帧自回归闭环里，哪条链路先撞墙</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-37\">三十七 · 精度塌陷：从“少步轨迹”到“帧间漂移”的链式放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-38\">三十八 · OOM 与显存水位：窗口长度与并发路数的乘积约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-39\">三十九 · 批抖动：控制节拍与批大小耦合下的时延方差</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-40\">四十 · 尾延迟：解码与采样预算的叠加点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-41\">四十一 · 静默降级：没有告警的失败最贵</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-42\">四十二 · 失效链诊断：从精度塌陷到静默降级的可观测断点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-43\">四十三 · 口径先立：这份材料能支撑什么读法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-44\">四十四 · 硬件档位：材料未给，但档位决定窗口与批的可行域</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-45\">四十五 · batch 与并发：帧时延与显存余量的折中面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-46\">四十六 · 指标怎么读：TTFT/TPOT 在帧自回归里的重新定义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-47\">四十七 · 哪些提升不可比：四类常见的口径错位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-48\">四十八 · 误差累积与窗口截断：评测必须携带的两个负向指标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-49\">四十九 · 迁移到非驾驶视频域：条件接口与回灌语义先改</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-50\">五十 · 迁到纯扩散/流匹配主干：蒸馏与缓存的耦合会松掉</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-51\">五十一 · 不适用边界：长程一致性与强指令耦合场景</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-52\">五十二 · 规模上限：窗口、批与显存的三角约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-53\">五十三 · 迁移检查清单与判断落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-far-drive-frame-autoregressive-video-2026-sec-54\">五十四 · 迁移边界：帧自回归推理骨架在何处成立、何处失效</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:482px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 482.0 423\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">接收当前控制指令与历史帧缓冲，拼成帧级条件输入；</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">对条件做编码并复用历史帧的 KV 缓存，避免重算旧帧；</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">以蒸馏后的少量流匹配步数采样当前帧潜变量；</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">VAE 解码当前帧并写入历史缓冲，滚动窗口淘汰最旧帧；</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">将新帧回灌为下一时刻条件，进入下一控制周期的生成。</text><line x1=\"82.0\" y1=\"342.2\" x2=\"82.0\" y2=\"359.2\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 358.2 L 86.5 358.2 L 82.0 366.2 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"366.2\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"388.7\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"392.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">6</text><text x=\"75.0\" y=\"393.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按批调度多路闭环仿真请求，监控每帧时延与显存水位。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-1\">一 · 控制周期里的那一帧：闭环在线服务的真实压力</h3>\n<p>设想一辆车在环仿真里跑城市场景：规划器每个控制周期（典型量级为几十毫秒）给出一个候选动作序列，仿真器必须立刻回答“如果这样打方向、这样给油，接下来几秒会看到什么”。回答的形式是视频——不是事后渲染的漂亮片段，而是能马上回灌给感知与规划模块的未来帧。这里的时间预算被切成两段：生成器拿到新指令后必须在周期内交出当前帧，规划器才能在同一节拍内评估动作后果。一旦生成时延超过控制周期，闭环就退化成开环：规划器评估的是过时的世界状态，动作后果的因果链断裂，仿真失去意义。</p>\n<p>这个场景把视频生成的评价标准彻底改写。离线生成关心的是整段视频的质量与多样性，可以花几分钟去噪；闭环在线服务关心的是<strong>单帧时延的确定性</strong>与<strong>长时展开下的稳定性</strong>。前者是硬约束，后者是软约束但会随时间放大。工程上真正难的是两者耦合：为了压时延而减少采样步数、缩短历史窗口，恰恰是最容易破坏长时一致性的两个旋钮。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-2\">二 · 旧方案的主流做法：整段离线去噪加滑窗切片</h3>\n<p>在 FAR-Drive 之前，把扩散或流匹配视频模型塞进闭环的常见做法是“整段生成 + 滑窗切片”：一次调用生成一段固定长度的视频（例如若干秒），取其中第一帧或前几帧交给规划器，下一周期再整体重跑一遍，或者用滑动窗口把上一段的后半截作为下一段的条件继续生成。这套做法直接继承了离线视频生成的推理栈：多步迭代采样、整段时空注意力、全序列 KV 或全序列激活驻留显存。</p>\n<p>它的代价结构非常清晰。设一段视频有 $F$ 帧、每帧潜变量长度为 $L$、采样步数为 $K$，则一次调用的去噪计算量大致正比于 $K \\cdot F \\cdot L^{2}$（注意力项）加上 $K \\cdot F \\cdot L \\cdot d$（线性投影项）。在闭环里，规划器每个周期只需要一帧，却要为整段 $F$ 帧付一次全量去噪的账。折算到“每有效帧”的成本被放大了 $F$ 倍，而其中 $F-1$ 帧的计算在下一个周期大概率被丢弃或重算。这就是旧方案最核心的浪费：<strong>计算粒度与控制粒度不匹配</strong>。</p>\n<div class=\"formula\">$$\\text{Cost}_{\\text{per-useful-frame}} \\;\\approx\\; \\frac{K \\cdot F \\cdot \\big(c_1 L^{2} + c_2 L d\\big)}{1}$$</div>\n<p>分子是整段去噪的实打实开销，分母是闭环真正消费的帧数。$F$ 越大，浪费越严重；而 $F$ 又不能太小，否则滑窗重叠比例上升、边界伪影与重复计算同时恶化。</p>\n<p>具体例子：一个 5 秒、若干帧的片段在滑窗方案下每周期重跑，若滑窗重叠一半，则相邻两次调用有一半帧被重复去噪。规划器只取最新一帧，意味着这一帧的边际成本里包含了整段的重算与重叠区的重复计算。工程上表现为 GPU 利用率看似很高，但有效吞吐（被闭环消费的帧/秒）极低。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-3\">三 · 显存与带宽：全序列驻留把批并发锁死</h3>\n<p>旧方案的第二个痛点在显存。整段去噪要求同时持有整段视频的潜变量、每层时空注意力的中间激活，以及 VAE 解码所需的工作区。显存占用随 $F$ 线性增长，且注意力中间量随 $F^{2}$ 或 $F \\cdot W$（$W$ 为窗口内帧数）增长。在多路仿真并发时，每路都要一份完整的整段缓冲，批大小被显存水位直接锁死：显存不够就只能降批，降批就意味着单位时间内能评估的候选动作变少，规划器的搜索质量下降。</p>\n<p>带宽侧同样吃紧。整段去噪每一步都要把全序列的 KV 或激活从 HBM 读回 SM，步数 $K$ 越多，重复搬运越多。设单步需要搬运的字节数为 $B$，则一段视频的 HBM 流量约为 $K \\cdot B$，而其中真正被闭环消费的只有最后一帧对应的那一小部分。带宽成为比算力更早触顶的瓶颈时，增加算力毫无意义——这是旧方案在 Blackwell 这类高算力、相对带宽受限的平台上尤其刺眼的结构性缺陷。</p>\n<table class=\"mini\"><thead><tr><th>旧方案环节</th><th>闭环中的实际代价</th><th>后果</th></tr></thead><tbody><tr><td>整段多步去噪</td><td>每周期为 $F$ 帧付 $K$ 步的账</td><td>有效帧成本放大 $F$ 倍，时延不可控</td></tr><tr><td>全序列注意力</td><td>激活随 $F$ 增长，中间量随 $F^{2}$ 增长</td><td>显存水位锁死批并发</td></tr><tr><td>全序列 KV 重算</td><td>每步重复搬运 $K \\cdot B$ 字节</td><td>带宽先于算力触顶</td></tr><tr><td>滑窗重叠</td><td>重叠区被重复去噪</td><td>吞吐虚高，边界伪影</td></tr></tbody></table>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-4\">四 · 误差沿帧回灌：滑窗方案掩盖不了的闭环特有失败</h3>\n<p>旧方案最隐蔽的痛点不在算力账上，而在误差传播。滑窗切片把上一段的尾部帧作为下一段的条件，这在形式上已经是自回归，但工程实现上常被当作“独立的整段生成”来处理：每段重新初始化采样轨迹，段与段之间只通过像素或潜变量的硬拼接传递条件。问题在于，扩散/流匹配的少步采样本身是有偏的，解码回像素再编码回潜变量会引入量化与重建误差，这些偏差一旦进入条件，就会在下一段被当作“真实历史”继续放大。</p>\n<p>闭环把这个过程变成正反馈：规划器基于带偏差的帧做决策，决策又作为新指令进入生成器，生成器再产出下一帧。误差不只是沿时间累积，还沿“生成—决策—再生成”的环路累积。滑窗方案因为每段都重跑全量去噪，看似“每段都新鲜”，实际上段间条件的不连续会在边界处产生跳变，规划器看到的世界出现不合理的突变，动作评估失真。材料明确指出自回归展开存在误差累积、早期帧偏差沿时间传播，且未给出长时闭环下的漂移量化与缓解手段——这正是旧方案无法回答、也非改不可的地方。</p>\n<p>具体例子：一段滑窗生成的视频在段边界处，由于两次独立采样的随机性与条件拼接的不一致，同一辆车的位置出现小幅跳变。单看视频不明显，但规划器对位置导数敏感，跳变被读成异常加速度，触发不必要的急刹评估。这类失败不会出现在离线质量指标里，只在闭环里暴露。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-5\">五 · 为什么非改不可：三个约束同时收紧</h3>\n<p>把上述痛点叠在一起，旧方案面对的是三个同时收紧的约束。第一，<strong>时延约束</strong>：单帧生成时延必须匹配控制周期，而整段去噪的时延由 $K \\cdot F$ 决定，两个因子都不受单帧需求控制。第二，<strong>显存约束</strong>：批内并发路数由整段缓冲的显存水位决定，窗口与批大小耦合，超时请求只能降批或缩短窗口，两者都损伤仿真保真度。第三，<strong>一致性约束</strong>：滑窗的段间不连续与误差回灌在闭环里被放大，且没有机制层面的缓解手段。</p>\n<p>这三者不是独立的工程取舍，而是同一个结构问题的三个投影：<strong>生成的计算单元（整段）大于闭环的消费单元（单帧）</strong>。只要计算单元不缩小到帧级，采样步数、缓存复用与显存占用就无法作为独立可调的一等变量来分配预算。FAR-Drive 的切入点正是把自回归单元从“段”改成“帧”：以历史帧潜变量与控制指令拼接为条件，逐帧少量步采样、立即解码回灌，历史帧 KV 以滚动窗口缓存复用，使单帧计算量不随展开时长线性增长。这一步改动的直接后果是，$K$、窗口长度与批大小从被动耦合变成可分别调度的旋钮——而这三个旋钮如何在实际服务里分配预算，正是后续精度、缓存与调度层面要展开的工程问题。</p>\n<p>需要强调的是，改成帧级自回归并没有消除误差累积，只是把它从“段边界的跳变”变成“沿帧连续的漂移”，并把固定滚动窗口的长程记忆截断摆上台面。材料确认这两点是主要待验证风险，且缺少可核验数字。因此判断这套改动是否成立，不能看离线画质，而要看闭环里单帧时延的尾部（是否稳定落在控制周期内）、窗口淘汰频率与帧间一致性漂移的联合表现——这三个监控项构成了旧方案与新方案之间真正的分水岭。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-6\">六 · 控制周期里的硬时延：为什么整段去噪在闭环中先失效</h3>\n<p>把镜头拉到一个在线仿真服务：规划器每个控制周期下发一条新指令（转向角、加速度），并需要在下一个周期到来前拿到“执行这条指令后未来若干帧会怎样”的画面，否则决策只能退回保守策略。旧栈的主流做法是把一段视频当作整体去噪——给定初始观测，扩散或流匹配模型以几十步迭代把整段潜变量从噪声搬到数据分布，再一次性 VAE 解码。这条路径在离线评测里质量很好，但它的时间结构是“批式”的：整段视频的采样预算必须在一次调用内花完，首帧可用时间等于整段完成时间。闭环不等整段，它等的是下一帧。于是采样步数 $K$ 与分辨率直接决定单帧时延，而单帧时延又必须落进控制周期 $T_{\\text{ctrl}}$ 内，约束写成 $\\,T_{\\text{sample}}(K)+\\,T_{\\text{dec}} \\le T_{\\text{ctrl}}\\,$，其中解码时延与采样时延同属一帧预算，任何一项超支都表现为规划器空转。</p>\n<p>更麻烦的是“条件新鲜度”。整段去噪在采样开始时就把条件冻结，中途到达的新指令无法进入去噪轨迹；若为每条指令重跑整段，GPU 上的算力与显存带宽被反复消耗在同一批历史帧上——历史帧的时空注意力被重算，KV 不保留，计算量随上下文长度线性上涨。表里这三列代价在旧栈上是耦合的，压其中一项往往抬高另一项。</p>\n<table class=\"mini\"><thead><tr><th>旧栈环节</th><th>系统代价</th><th>失效条件</th></tr></thead><tbody><tr><td>整段多步去噪</td><td>单帧时延随步数线性增长，首帧可用时间被整段拖长</td><td>控制周期短于整段采样时间</td></tr><tr><td>条件冻结</td><td>新指令需重跑，算力与带宽重复支出</td><td>指令在采样中途到达</td></tr><tr><td>无 KV 复用</td><td>历史帧注意力重算，显存与带宽随上下文增长</td><td>闭环展开时长变长</td></tr></tbody></table>\n<p>还有一个闭环特有的失效条件：把整段扩散简单改成滑窗推理，看起来是“流式”，实际上每帧仍以多步去噪独立生成，且上一帧的解码结果不回灌为下一帧条件，帧间没有因果链，规划器看到的动作后果在时间上不连贯；一旦回灌，误差又会沿帧传播——早期帧的偏差进入下一帧条件，逐帧放大。这正是旧栈非改不可的地方：它既给不出匹配控制节拍的帧级时延，也没有把“历史帧条件 + 当前指令”组织成可复用的滚动状态。FAR-Drive 的切入点是把自回归单元下沉到帧、把采样步数用蒸馏压到少量步、把历史帧 KV 以滚动窗口缓存复用（机制细节见本卷帧自回归与 KV 缓存小节），从而让单帧计算量不随展开时长线性增长；代价是窗口外历史被截断、长程一致性受窗口长度约束，且少步蒸馏本身会带来帧间漂移，这些都需要在部署时以窗口长度与批大小作为可调杠杆来对冲。</p>\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-7\">七 · 请求到达形态：控制节拍驱动的帧级泊松流</h3>\n<p>FAR-Drive 的请求不是离线批式的整段视频作业，而是由闭环控制周期切分出的帧级请求流。每个控制周期到来时，规划器下发一条新的控制指令，生成器必须在该周期预算内产出一帧并回灌。因此请求到达率由控制频率决定，而非由客户端并发决定；单路仿真的请求间隔近似恒定，多路仿真叠加后形成准周期的到达序列。测量口径上，需要区分三个量：控制周期 <em>T</em><sub>ctrl</sub>（规划器节拍）、请求到达间隔 <em>T</em><sub>arr</sub>（指令写入队列的时刻差）、以及服务开始时刻 <em>T</em><sub>start</sub>。排队时延 <em>W</em> = <em>T</em><sub>start</sub> − <em>T</em><sub>arr</sub>，端到端帧时延 <em>L</em> = <em>T</em><sub>done</sub> − <em>T</em><sub>arr</sub>。可核查的做法是在指令入队与帧写回缓冲两处打时间戳，用单调时钟，禁用墙钟，避免 NTP 抖动污染长尾统计。</p>\n<p>输入长度分布不是文本 token 长度，而是条件张量的规模：历史帧潜变量数量 × 每帧潜变量空间尺寸 + 控制指令向量维度。滚动窗口长度 <em>W</em><sub>hist</sub> 决定条件中历史帧的个数，因此输入长度在窗口填满前随帧序号线性增长，填满后被钳制在 <em>W</em><sub>hist</sub>。这形成一个明确的冷启动斜坡：前 <em>W</em><sub>hist</sub> 帧的输入长度递增，KV 缓存逐帧追加；之后进入稳态，每帧淘汰最旧帧、追加最新帧，缓存尺寸恒定。测量输入长度分布必须按帧序号分段统计，把斜坡段与稳态段分开报告，否则均值会被冷启动段拉低，掩盖稳态的真实条件规模。</p>\n<p>系统代价在这里体现为显存与带宽的耦合：稳态下 KV 缓存占用正比于 <em>W</em><sub>hist</sub> × 批内并发路数 <em>B</em>，而每帧需从缓存读取全部窗口内历史帧的 K/V 参与跨帧时间维注意力，读取带宽正比于 <em>W</em><sub>hist</sub> × <em>B</em> × 每帧 KV 字节数。举例：若单路仿真窗口为 <em>W</em><sub>hist</sub> 帧、并发 <em>B</em> 路，则跨帧注意力每帧的 KV 读取量为 <em>B</em> · <em>W</em><sub>hist</sub> · <em>S</em><sub>kv</sub>，其中 <em>S</em><sub>kv</sub> 为单帧 KV 字节数；这一项随并发线性上升，是批大小无法无限放大的直接原因。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-8\">八 · 并发与批大小：时延预算倒推的上界</h3>\n<p>批大小 <em>B</em> 在 FAR-Drive 中不是吞吐优化变量，而是时延约束下的因变量。单帧预算 <em>T</em><sub>ctrl</sub> 需覆盖四段：条件拼接与编码、少步流匹配采样（<em>K</em> 步）、VAE 解码、以及回灌写缓冲。设单帧在批大小 <em>B</em> 下的计算时间为 <em>t</em><sub>comp</sub>(<em>B</em>)，KV 读取时间为 <em>t</em><sub>kv</sub>(<em>B</em>, <em>W</em><sub>hist</sub>)，解码时间为 <em>t</em><sub>dec</sub>(<em>B</em>)，则可行性条件为：</p>\n<div class=\"formula\">$$t_{\\text{comp}}(B) + t_{\\text{kv}}(B, W_{\\text{hist}}) + t_{\\text{dec}}(B) + t_{\\text{write}} \\le T_{\\text{ctrl}}$$</div>\n<p>由于 <em>t</em><sub>comp</sub> 与 <em>t</em><sub>dec</sub> 在 GPU 上随 <em>B</em> 呈次线性增长（批内并行填充 SM），而 <em>t</em><sub>kv</sub> 随 <em>B</em> 线性增长（带宽受限），存在一个由带宽项主导的拐点：超过该拐点后，增大批只会拉长单帧时延而不提升每周期产出帧数。工程判断是先用小批测出 <em>t</em><sub>kv</sub> 的斜率，再反解 <em>B</em><sub>max</sub>，而不是先定批再调时延。</p>\n<p>测量口径要求报告批内时延分布而非均值：同一批内各请求的完成时刻不同，批尾请求的时延显著高于批首，长尾主要由批尾构成。可核查的指标包括 P50、P99 单帧时延，批内时延极差，以及超时率（<em>L</em> &gt; <em>T</em><sub>ctrl</sub> 的帧占比）。超时处理按材料所述为降批或缩短窗口：降批降低 <em>t</em><sub>kv</sub>，缩短窗口降低 <em>W</em><sub>hist</sub> 同时降低缓存占用与读取量，两者都以牺牲历史上下文为代价换取时延达标。</p>\n<p>具体例子：多路仿真并发时，若某路请求因规划器动作评估耗时波动而延迟入队，其帧会与后续周期的帧在队列中重叠，形成瞬时到达尖峰。此时调度器若维持原批大小，批尾帧必然超时；若降批，则吞吐下降但每帧时延回到预算内。这一权衡的量化口径是单位控制周期内成功回灌的帧数与超时帧数之比，而非单纯的平均时延。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-9\">九 · SLO 的定义：单帧时延而非吞吐</h3>\n<p>闭环驾驶的 SLO 是单帧生成时延匹配控制周期，即 <em>L</em> ≤ <em>T</em><sub>ctrl</sub>，且帧间时延抖动有界，因为规划器按固定节拍消费帧，抖动会导致仿真时间轴与真实控制节奏失配。这与离线视频生成的吞吐型 SLO 有本质区别：后者优化每秒帧数，前者优化每帧截止时刻的满足率。可核查的 SLO 表述应写成「在并发 <em>B</em> 路、窗口 <em>W</em><sub>hist</sub> 帧、蒸馏步数 <em>K</em> 的条件下，P99 单帧时延不超过 <em>T</em><sub>ctrl</sub>」，把三个自变量显式写进 SLO，否则该 SLO 不可复现。</p>\n<p>时延预算的分解需按段打点：采样段包含 <em>K</em> 步流匹配迭代，每步含一次时空注意力前向与一次 KV 读取；解码段为 VAE 前向；写回段为缓冲写入与窗口淘汰。由于材料未给出分辨率、解码吞吐与显存峰值，端到端帧率无法核算，只能定性判断解码时延计入单帧预算且不可忽略——VAE 解码是逐帧执行的独立前向，其计算量与潜变量空间尺寸成正比，在少步采样把采样段压到很小后，解码段可能成为预算中的主要项。这一判断的验证方式是分别对采样段与解码段计时，比较两者占比。</p>\n<p>长尾来源有三类：批尾效应（同批内完成时刻离散）、窗口淘汰抖动（淘汰最旧帧时缓存重排或地址不连续导致的额外拷贝）、以及指令到达抖动（规划器侧评估耗时波动传导到入队时刻）。测量长尾必须把这三类分开归因，用分段计时而非端到端单一数字，否则无法判断该降批还是该改缓存布局。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-10\">十 · 负载塑造方案：窗口与批的联合定标</h3>\n<p>负载形态直接决定三个方案参数：滚动窗口长度 <em>W</em><sub>hist</sub>、批大小上界 <em>B</em><sub>max</sub>、蒸馏步数 <em>K</em>。三者与显存、带宽、时延的关系可写成约束组：显存占用 <em>M</em> ≈ <em>B</em> · <em>W</em><sub>hist</sub> · <em>S</em><sub>kv</sub> + <em>M</em><sub>weights</sub> + <em>M</em><sub>act</sub>，其中 <em>M</em><sub>weights</sub> 为生成器与 VAE 权重占用，<em>M</em><sub>act</sub> 为批内激活占用；带宽需求 <em>R</em> ≈ <em>B</em> · <em>W</em><sub>hist</sub> · <em>S</em><sub>kv</sub> / <em>T</em><sub>ctrl</sub>。给定显存档位与可用带宽，这两个式子给出 (<em>B</em>, <em>W</em><sub>hist</sub>) 的可行域边界。工程做法是先按显存定 <em>W</em><sub>hist</sub> 的上界，再按带宽定 <em>B</em><sub>max</sub>，最后用实测时延验证 <em>K</em> 步是否落在预算内。</p>\n<p>反过来，方案也限制负载：固定窗口截断长程历史，意味着闭环展开超过 <em>W</em><sub>hist</sub> 帧后，早期帧的上下文不可见，长时一致性受窗口长度约束。这是方案对负载的反向塑造——负载的「记忆需求」被窗口硬性截断，规划器若依赖长程历史评估动作后果，则窗口长度成为仿真可信度的上限。可核查的测量是帧间一致性漂移：在固定窗口下，比较第 <em>n</em> 帧与第 <em>n</em>−<em>W</em><sub>hist</sub> 帧在重叠区域的像素或潜变量差异，随 <em>n</em> 增大观察该差异是否单调上升，以此量化截断代价。</p>\n<p>具体例子：若显存余量只允许 <em>B</em> · <em>W</em><sub>hist</sub> 达到某固定乘积，则提高并发必须缩短窗口，缩短窗口直接削弱长程一致性；反之延长窗口必须降并发，降并发降低单位周期内可评估的仿真路数。这一乘积守恒关系是容量规划的核心，测量口径是记录每次调度决策时的 (<em>B</em>, <em>W</em><sub>hist</sub>) 组合与对应的超时率、漂移指标，形成可回溯的定标表。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-11\">十一 · 可核查的测量口径清单</h3>\n<p>为避免不可核验的表述，本部分给出可执行的测量口径，全部基于材料中已确认的机制量，不引入未给出的数字。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>指标</th><th>定义</th><th>打点位置</th><th>用途</th></tr>\n</thead>\n<tbody>\n<tr><td>单帧时延 <em>L</em></td><td><em>T</em><sub>done</sub> − <em>T</em><sub>arr</sub></td><td>指令入队、帧写回缓冲</td><td>判定 SLO 满足率</td></tr>\n<tr><td>排队时延 <em>W</em></td><td><em>T</em><sub>start</sub> − <em>T</em><sub>arr</sub></td><td>入队、调度器派发</td><td>区分调度延迟与计算延迟</td></tr>\n<tr><td>采样段耗时</td><td><em>K</em> 步流匹配迭代总时间</td><td>采样前、采样后</td><td>定位蒸馏步数预算</td></tr>\n<tr><td>解码段耗时</td><td>VAE 前向时间</td><td>解码前、解码后</td><td>判断解码是否成为主项</td></tr>\n<tr><td>KV 读取量</td><td><em>B</em> · <em>W</em><sub>hist</sub> · <em>S</em><sub>kv</sub></td><td>注意力前向入口</td><td>核算带宽需求</td></tr>\n<tr><td>显存水位</td><td>缓存 + 权重 + 激活峰值</td><td>每帧采样后</td><td>约束批与窗口乘积</td></tr>\n<tr><td>窗口淘汰频率</td><td>单位帧数内淘汰次数</td><td>缓冲写回</td><td>识别淘汰抖动</td></tr>\n<tr><td>帧间一致性漂移</td><td>第 <em>n</em> 帧与第 <em>n</em>−<em>W</em><sub>hist</sub> 帧重叠区差异</td><td>解码后</td><td>量化窗口截断代价</td></tr>\n</tbody>\n</table>\n<p>输入长度分布的测量需按帧序号分段：斜坡段（帧序号 ≤ <em>W</em><sub>hist</sub>）报告条件张量规模的递增序列，稳态段报告恒定规模及其方差。并发测量需记录瞬时在途请求数而非配置的并发上限，因为超时降批会使实际并发低于配置值。批大小测量需同时记录调度决策值与批内实际完成帧数，二者在超时降批场景下不一致。</p>\n<p>长尾归因的伪代码思路：对每帧记录四段时间戳，计算各段耗时，按批内位置（批首/批中/批尾）分组统计 P99；若批尾 P99 显著高于批首，则长尾由批内离散主导，应缩批；若各位置 P99 接近但整体偏高，则长尾由带宽或解码主导，应缩短窗口或调整解码并行度。这一归因流程不依赖任何未给出的数字，只依赖打点位置与分组逻辑。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-12\">十二 · 负载与方案的耦合边界</h3>\n<p>负载塑造方案的上界是显存与带宽，方案限制负载的下界是窗口截断与批内离散。二者的耦合点在于乘积 <em>B</em> · <em>W</em><sub>hist</sub>：它同时出现在显存约束、带宽约束与一致性约束中，是唯一一个同时被三方拉扯的变量。工程判断是把这个乘积作为容量规划的一等参数，在部署前用实测的 <em>S</em><sub>kv</sub>、可用带宽与显存档位解出可行区间，再在区间内按仿真路数需求与一致性需求分配。任何声称固定批大小或固定窗口长度的方案，都隐含了对该乘积的未声明假设，在并发或分辨率变化时失效。</p>\n<p>具体机制上，窗口淘汰时的缓存布局决定了长尾的下限：若淘汰采用环形缓冲，最旧帧的槽位被新帧覆写，KV 读取的地址连续性得以保持，淘汰抖动被消除；若采用重排或压缩，则每次淘汰引入额外拷贝，抖动随淘汰频率上升。测量口径是比较环形缓冲与重排两种布局下窗口淘汰频率与批尾 P99 的关系，前者应呈现淘汰频率与 P99 解耦，后者应呈现正相关。这一比较不需要具体数字即可执行，结论以相关性方向呈现。</p>\n<p>最后落在工程判断上：FAR-Drive 的负载形态是控制节拍驱动的准周期帧流，其 SLO 是单帧截止时刻满足率而非吞吐，因此批大小必须由时延预算倒推而非由吞吐目标正推；窗口长度必须与批大小联合定标，二者乘积受显存与带宽双重约束；长尾归因必须按批内位置与耗时段分组，才能区分降批、缩窗与改缓存布局三种处置。这些口径共同构成该工作负载侧的可核查测量框架，后续精度与并行方案的效果评估应在此框架下进行，否则时延数字不可比。</p>\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-13\">十三 · 从帧自回归的算子清单说起</h3>\n<p>FAR-Drive 的单帧生成路径在算子上并不特殊：条件拼接后进入时空注意力堆栈，每层含 QKV 投影、注意力打分、输出投影，再经 FFN 的两级线性层，末端由 VAE 解码器把潜变量还原为像素。真正决定这条路径在 Blackwell 上跑多快、跑多省的，不是算子种类，而是每个算子的数值格式与累加路径。帧自回归把每帧采样压到少量蒸馏步，意味着单帧内可摊销的固定开销变少，kernel 启动、权重读取与解码的占比上升；此时把矩阵乘从 BF16 降到 FP8 或 NVFP4，收益不再只是峰值算力翻倍，而是权重带宽与 L2 驻留压力的同步下降。历史帧 KV 缓存复用又给精度问题加了一层：缓存里的 K/V 是上一帧以某种精度写入的，本帧读出后要与新帧的 Q 做打分，若写入与读出格式不一致，就会引入与展开时长相关的漂移。</p>\n<p>因此本部分的角度不是罗列 Tensor Core 规格，而是把「格式—累加—误差—缓存」串成一条可核算的链：每个格式选择都要回答它在单帧时延预算里省下多少带宽、在帧间一致性上付出多少误差。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-14\">十四 · 四种格式在单帧路径上的分工</h3>\n<p>FP16 与 BF16 的差别不在尾数位数的绝对值，而在动态范围与累加器宽度的配合。BF16 的 8 位指数与 FP32 同宽，条件拼接后控制指令嵌入与历史帧潜变量的量级差异大，BF16 不会因指令 token 的小幅值被压到次正规数而丢信息；FP16 的 5 位指数在潜变量激活值跨越多个数量级时更容易溢出。工程判断是：条件编码与 VAE 解码两侧留在 BF16，因为这两处的激活分布随控制指令变化剧烈，且解码时延已计入单帧预算，不值得为半档带宽冒险。</p>\n<p>FP8 分 E4M3 与 E5M2 两种，前者尾数多一位适合权重与激活，后者动态范围大适合梯度类场景，推理侧几乎只用 E4M3。FP8 的关键约束是缩放因子必须按张量或按通道校准，且校准必须在闭环滚动下稳定：若某帧的控制指令使激活分布突变，固定缩放因子会把大量值压进饱和区，误差沿回灌链传播。NVFP4 把尾数压到 3 位、块内共享缩放，权重侧收益最大，激活侧需要更细的块粒度才能保住帧间一致性；它适合放在 FFN 的权重上，而不适合放在注意力的 QKV 投影输出上，因为后者直接参与打分，量化噪声会被 softmax 放大。</p>\n<table class=\"mini\"><thead><tr><th>位置</th><th>建议格式</th><th>主要代价</th><th>风险点</th></tr></thead><tbody>\n<tr><td>条件编码 / 指令嵌入</td><td>BF16</td><td>带宽高于 FP8</td><td>动态范围需求高，不宜降</td></tr>\n<tr><td>QKV 投影权重</td><td>FP8 E4M3</td><td>需校准缩放</td><td>打分噪声经 softmax 放大</td></tr>\n<tr><td>FFN 权重</td><td>NVFP4</td><td>块缩放元数据开销</td><td>块粒度过粗伤帧间一致性</td></tr>\n<tr><td>KV 缓存写入</td><td>FP8 或 BF16</td><td>缓存容量与读出带宽</td><td>写入/读出格式不一致引入漂移</td></tr>\n<tr><td>VAE 解码</td><td>BF16</td><td>解码时延占单帧预算</td><td>像素域误差直接可见</td></tr>\n</tbody></table>\n<p>具体例子：把 FFN 权重从 BF16 换到 NVFP4，权重读取字节数降到约四分之一，在单帧只跑少量蒸馏步的场景下，权重带宽往往比算力更早成为瓶颈，因此这一换挡对帧时延的贡献可能大于把注意力打分换成 FP8；但若块缩放粒度粗到跨通道共享，FFN 输出的帧间抖动会在回灌后累积成可见的闪烁。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-15\">十五 · 累加精度与误差如何在回灌链上放大</h3>\n<p>Tensor Core 的乘加在低精度输入下仍以 FP32 累加，这一点在 Blackwell 上不变；真正要解释的是累加顺序与分块对误差的影响。以注意力打分为例，设查询向量 $\\mathbf{q}$ 与键向量 $\\mathbf{k}_j$ 均以 FP8 存储、缩放因子为 $s_q, s_k$，则打分近似为</p>\n<div class=\"formula\">$$\\tilde{a}_{j}=s_q s_k\\sum_{i=1}^{d}\\hat{q}_i\\hat{k}_{j,i}+\\epsilon_{\\mathrm{acc}},\\qquad \\epsilon_{\\mathrm{acc}}\\sim \\mathcal{O}\\!\\left(\\sqrt{d}\\,\\epsilon_{m}\\right)$$</div>\n<p>其中 $\\hat{q},\\hat{k}$ 是量化后的整数表示，$\\epsilon_m$ 是单次乘加的舍入量级，$d$ 是头维。逐项解释：$s_q s_k$ 把整数点积还原到实数域，两个缩放因子的乘积误差直接进入打分；求和项由 Tensor Core 在 FP32 累加器中完成，但分块归约的顺序决定了 $\\epsilon_{\\mathrm{acc}}$ 的量级——块越大，块内部分和越长，抵消越严重时相对误差越高。softmax 对打分的敏感度是非线性的，打分误差 $\\delta$ 经 softmax 后转化为注意力权重的相对扰动约为 $\\delta$ 量级，再乘上值向量进入输出，于是单层的量化噪声被放大一次。</p>\n<p>回灌链把这件事变成时间问题。设第 $t$ 帧解码结果为 $\\mathbf{x}_t$，它既是输出又是第 $t+1$ 帧的条件，若每帧引入的潜变量扰动为 $\\boldsymbol{\\xi}_t$，则展开 $T$ 帧后的偏差可写成</p>\n<div class=\"formula\">$$\\mathbf{e}_{T}=\\sum_{t=1}^{T}\\left(\\prod_{\\tau=t+1}^{T}\\mathbf{J}_{\\tau}\\right)\\boldsymbol{\\xi}_{t}$$</div>\n<p>$\\mathbf{J}_{\\tau}$ 是第 $\\tau$ 步生成映射对条件的雅可比，$\\prod$ 表示沿时间的复合。逐项解释：$\\boldsymbol{\\xi}_t$ 是单帧量化与少步蒸馏共同引入的扰动；$\\mathbf{J}_{\\tau}$ 的谱半径若大于 1，早期帧的误差会被后续帧放大，这正是闭环自回归区别于离线整段去噪的失败模式；若谱半径小于 1，误差会衰减，但衰减速度取决于条件拼接中历史帧的权重。工程含义是：量化误差不能只看单帧 PSNR，要看它在 $\\mathbf{J}$ 主导下的传播；降低 $\\boldsymbol{\\xi}_t$ 的最直接手段是提高 KV 缓存写入精度与注意力打分的累加块大小，而不是全局换格式。</p>\n<p>代价侧：FP32 累加器在 TMEM 中占用更多容量，若把累加精度降到 FP16 累加，注意力打分的吞吐可上升，但 $\\epsilon_{\\mathrm{acc}}$ 随 $d$ 增长更快，在长头维上会直接改变 softmax 的排序，进而改变帧间一致性；这是用吞吐换一致性的典型折中，需按窗口长度实测。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-16\">十六 · Blackwell 特性如何改变单帧 kernel 的形状</h3>\n<p>tcgen05 是 Blackwell 上 Tensor Core 的指令族，其意义在于把矩阵乘的发起、累加与结果搬运拆成可流水化的阶段，并让累加器驻留在 TMEM 而非寄存器堆。对 FAR-Drive 的单帧路径，这带来两个直接后果：其一，QKV 投影与 FFN 的大矩阵乘可以把累加器留在 TMEM 中跨多个 MMA 指令复用，减少寄存器压力与中间结果的搬出；其二，TMEM 容量成为新的约束——若同时驻留多个头的打分累加器与 FFN 中间结果，TMEM 会被占满，迫使 kernel 分阶段串行，反而拉长单帧时延。</p>\n<p>2-SM MMA 让两个 SM 协同完成一次更大的矩阵乘，把单指令的 M 维或 N 维扩大，等效于提高单次 MMA 的计算强度并摊薄权重读取。对帧自回归而言，单帧的批维往往很小（一路仿真一帧，或多路并发拼批），2-SM MMA 的价值在于把「小 batch、大权重」的形态从受限于单 SM 的窄矩阵乘中解放出来；代价是跨 SM 的同步与数据交换，若批太小，协同开销会吃掉收益。第五代 Tensor Core 在低精度格式上的吞吐提升只有在数据供给跟得上时才兑现，因此 kernel 的瓶颈判断要先看权重带宽与 KV 缓存读出带宽，再看峰值算力。</p>\n<p>具体例子：把注意力的 QKV 投影做成一个以 tcgen05 发起、累加器驻留 TMEM 的 kernel，并把 FFN 的两级线性层合并为一次 2-SM MMA 的分块调度，可以在单帧只跑少量蒸馏步时减少 kernel 启动次数与中间张量往返；但若 KV 缓存以 FP8 写入、以 BF16 读出，格式转换会插入额外的搬运阶段，抵消部分收益。显存侧，TMEM 与共享内存的占用决定了单 SM 能并发多少路仿真请求，进而决定批大小与单帧时延的折中点。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-17\">十七 · 把精度选择落到帧时延预算上</h3>\n<p>单帧时延预算由采样步数、每步的注意力与 FFN 计算、KV 缓存读出、VAE 解码四段构成。设单帧需 $K$ 步蒸馏采样，第 $k$ 步的计算量为 $C_k$、权重读取字节为 $B_k$、KV 读出字节为 $M_k$，则单帧时延的粗略下界为</p>\n<div class=\"formula\">$$T_{\\mathrm{frame}}\\gtrsim \\sum_{k=1}^{K}\\max\\!\\left(\\frac{C_k}{\\Pi_{\\mathrm{eff}}},\\ \\frac{B_k+M_k}{\\mathrm{BW}}\\right)+T_{\\mathrm{dec}}$$</div>\n<p>逐项解释：$\\Pi_{\\mathrm{eff}}$ 是该格式下的有效算力，受 Tensor Core 格式吞吐与数据供给共同约束；$\\mathrm{BW}$ 是显存带宽；$\\max$ 表示每步要么算力受限要么带宽受限，低精度格式降低 $B_k$ 与 $M_k$ 的同时提高 $\\Pi_{\\mathrm{eff}}$，但只有当带宽项原本占优时，换格式才真正缩短 $T_{\\mathrm{frame}}$；$T_{\\mathrm{dec}}$ 是 VAE 解码时延，它与采样步数无关，因此在少步蒸馏下占比上升，是精度选择必须保护的段落。工程判断：先用这一式子判断单帧是算力受限还是带宽受限，再决定把 FP8 放在权重还是激活、把 NVFP4 放在 FFN 还是注意力；若 $T_{\\mathrm{dec}}$ 已占预算大头，继续压采样精度对帧时延的边际收益递减。</p>\n<p>KV 缓存复用让 $M_k$ 随窗口长度增长而非随展开时长增长，但缓存写入格式决定了 $M_k$ 的字节数：FP8 写入使 $M_k$ 减半，代价是读出后与 BF16 查询做打分时的格式转换与精度损失。窗口越长，$M_k$ 在预算中的权重越大，此时缓存格式的选择比权重格式更影响帧时延；窗口短、批大时则相反。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-18\">十八 · 工程判断：格式表要跟窗口与批一起定</h3>\n<p>把上述链条收束成可执行的判断：精度方案不是全局一张表，而是随滚动窗口长度与批内并发路数变化的二维表。窗口长、单路仿真时，KV 缓存读出带宽主导，缓存写入用 FP8、注意力打分用 FP8 输入配 FP32 累加、FFN 权重用 NVFP4，解码保 BF16；窗口短、多路并发时，批维把小矩阵乘拼大，2-SM MMA 与 tcgen05 的协同收益上升，此时应优先保证 TMEM 不被多头累加器占满，宁可把部分投影留在 BF16 以换取并发路数。误差侧的统一约束是回灌链：任何格式变更都要在窗口长度上验证 $\\mathbf{J}$ 主导下的漂移，而不是只看单帧指标；KV 缓存写入与读出格式必须一致，否则格式转换本身就成为漂移源。最后，VAE 解码的精度不随采样格式联动下调，因为它是唯一直接进入像素域、被规划器与回灌同时消费的段落。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-19\">十九 · 精度边界：少步蒸馏下的数值误差与 Blackwell 算子代价</h3>\n<p>帧自回归把每帧采样预算压到少量步，这直接改变了数值精度的容错结构：多步去噪中误差可被后续步部分修正，而少步轨迹里每一步的舍入误差都更接近终值。若在 <span class=\"inline\">FP8</span> 或 <span class=\"inline\">NVFP4</span> 下做注意力与 GEMM，量化误差会经 VAE 解码写入历史缓冲，再作为下一帧条件回灌——误差不再是一次性的，而是被闭环放大。可写的判据是逐帧相对误差的传播界：设第 <span class=\"inline\">t</span> 帧潜变量误差为 <span class=\"inline\">e_t</span>，条件拼接与注意力的 Lipschitz 常数记为 <span class=\"inline\">L</span>，则 <span class=\"inline\">e_t ≤ L·e_{t-1} + δ_t</span>，其中 <span class=\"inline\">δ_t</span> 是本帧量化与少步采样的新增误差；当 <span class=\"inline\">L&gt;1</span> 时误差沿帧指数增长，<span class=\"inline\">L&lt;1</span> 才被窗口截断吸收。这解释了为何低精度不能只看单帧 PSNR：必须测 <span class=\"inline\">L</span> 与窗口长度的联合行为。</p>\n<p>Blackwell 侧的代价落在两处。其一是 <span class=\"inline\">tcgen05</span> 与 TMEM：MMA 累加器驻留张量内存，FP8/NVFP4 输入配 FP32 累加可保住长归约的精度，但 TMEM 容量约束了单 CTA 能并发的累加器数量，2-SM MMA 虽把两个 SM 的算力拼给同一 MMA，却要求操作数布局与同步更严格，帧内空间维与跨帧时间维分别切分后，跨帧注意力的 KV 复用会与 2-SM 的配对粒度冲突，切分不当就退化为单 SM 路径。其二是带宽：KV 缓存复用省了重算，但每帧仍要把窗口内历史 KV 从 HBM 拉进片上，窗口长度与批内并发路数共同决定这部分流量，低精度虽减半字节数，却把误差压进了回灌链路。</p>\n<table class=\"mini\"><thead><tr><th>精度档</th><th>主要收益</th><th>闭环风险</th></tr></thead><tbody><tr><td>BF16</td><td>累加稳定，误差传播可控</td><td>KV 带宽与显存占用最高</td></tr><tr><td>FP8</td><td>GEMM 吞吐与 KV 字节数减半</td><td>少步轨迹下 δ_t 抬升，需监控 L</td></tr><tr><td>NVFP4</td><td>权重与激活进一步压缩</td><td>解码后帧间漂移，窗口截断难吸收</td></tr></tbody></table>\n<p>工程判断应落在可观测的失效条件上：当窗口淘汰频率升高、帧间一致性漂移超出规划器可接受范围，或单帧时延因 TMEM 争用与 2-SM 配对失败而超出控制周期，就应回退精度档或缩短窗口，而不是继续加批。低精度在这里不是免费的吞吐，它把误差从单帧指标转移到了闭环稳定性上，必须与窗口长度、批大小一起作为联调变量。</p>\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-20\">二十 · 显存账本的三本账：权重、激活、KV</h3>\n<p>在 FAR-Drive 的帧自回归形态下，显存不是一块模糊的“占用”，而是三本必须分开记的账。第一本是权重账：生成器主干（流匹配去噪网络）、VAE 解码器、以及条件编码器各自的参数，在推理时是常驻的；若采用 NVFP4/FP8 权重，账本按每参数字节数折算，但 Blackwell 的 tcgen05 MMA 要求权重以特定布局驻留，转置副本与 scale 因子会额外占一小块，不能按裸参数量简单乘。第二本是激活账：每帧一次前向的中间张量，峰值出现在时空注意力与 MLP 展开处，随批大小与帧分辨率线性放大，且是瞬态的——它决定的是“能不能跑下这一帧”，而不是“能不能常驻”。第三本是 KV 账：历史帧潜变量在时间维注意力中产生的 K/V 张量，被缓存复用，是唯一随闭环展开时长增长的账目，也是本部分的主角。</p>\n<p>三本账的约束性质完全不同。权重账是静态的、可预算的；激活账是峰值的、与批调度耦合的；KV 账是滚动的、与窗口长度和并发路数耦合的。工程上把三者混成一个“显存水位”去调度，会在窗口满、批内多路并发时突然撞墙——因为撞墙的往往不是权重，而是 KV 加激活的瞬时叠加。</p>\n<div class=\"formula\">$$M_{\\text{total}} = \\underbrace{P\\cdot b_w}_{\\text{权重}} + \\underbrace{B\\cdot A_{\\text{peak}}(H,W,d)}_{\\text{激活峰值}} + \\underbrace{B\\cdot L_w\\cdot 2\\cdot n_l\\cdot d_{\\text{kv}}\\cdot b_{\\text{kv}}}_{\\text{KV 缓存}} + M_{\\text{workspace}}$$</div>\n<p>其中 $P$ 为参数量、$b_w$ 为每参数字节，$B$ 为批内并发路数，$L_w$ 为滚动窗口帧数，$n_l$ 为层数，$d_{\\text{kv}}$ 为每层 K/V 的头维展开宽度，系数 2 表示 K 与 V 各一份，$b_{\\text{kv}}$ 为 KV 的存储字节。$M_{\\text{workspace}}$ 是通信缓冲、VAE 解码临时区与框架自身的池化开销。这个式子的价值不在于精确，而在于它把“窗口长度”和“并发路数”显式放进了乘法项——这正是 FAR-Drive 批调度要折中的两个旋钮。</p>\n<p>举一个可复算的例子：设某档配置下 $P=8\\times10^9$ 参数、权重按 1 字节/参数（FP8 量级）驻留，则权重账约 8 GB；若 KV 每帧每层合计 0.5 MB 量级、层数取 40，则单路每帧 KV 约 20 MB，窗口 16 帧即 320 MB/路，8 路并发就是 2.5 GB；激活峰值若按每路 1 GB 估，8 路再叠 8 GB。合计已逼近 20 GB 量级，此时若把窗口从 16 拉到 32，KV 项翻倍到 5 GB，水位立刻吃紧。这就是为什么窗口长度必须作为一等调度变量，而不是配置里写死的常数。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-21\">二十一 · 分页与块表：把 KV 从“连续大数组”改成“可拼装的页”</h3>\n<p>帧自回归的 KV 缓存有一个与 LLM 不同的性质：它按帧追加，且窗口满后从最旧端淘汰。若按连续大数组分配，每帧追加都要在尾部预留增长空间，淘汰又要前移，碎片与拷贝代价高。工程上的做法是分页：把 KV 按固定帧数（例如每页 1 帧或 2 帧）切成页块，用一个块表记录“逻辑帧序 → 物理页”的映射。追加即分配新页写入，淘汰即把最旧页归还池子，块表只改指针，不搬数据。</p>\n<p>分页带来的直接收益是显存池化：不同并发路数的窗口可以共享同一个页池，某一路缩短窗口时释放的页立刻可被另一路复用，水位由“活跃页总数”而非“各路预留上限之和”决定。代价是注意力内核必须按块表做间接寻址，跨页的 K/V 在时间维注意力中不再是连续切片，内核要按页粒度发起多次加载，或在页内做局部归约再合并。这会把时间维注意力的有效带宽利用率压低一档，尤其在页较小、页数较多时，间接寻址的元数据开销上升。</p>\n<p>伪代码思路如下：</p>\n<div class=\"formula\">$$\\begin{aligned}\n&amp;\\text{for each new frame } t:\\ \\text{page} \\leftarrow \\text{pool.alloc}();\\ \\text{write } K_t,V_t \\text{ into page};\\\\\n&amp;\\text{block\\_table}[t] \\leftarrow \\text{page};\\ \\text{if } |\\text{window}| &gt; L_w:\\ \\text{pool.free}(\\text{block\\_table}[t-L_w]);\\\\\n&amp;\\text{attn} \\leftarrow \\text{PagedAttention}(Q_t,\\ \\text{gather}(K,V)\\ \\text{via block\\_table})\n\\end{aligned}$$</div>\n<p>系统代价落在两处：一是内核复杂度，分页注意力的实现比连续切片多一层索引，单帧时延里多出固定比例的寻址开销；二是页大小的选择，页太小则元数据与间接寻址频繁，页太大则淘汰粒度粗、池化不灵活，窗口截断时浪费半页。对 FAR-Drive 这种窗口长度本身是调度变量的场景，页大小应与最小可调度窗口对齐，让“缩短窗口”能以整页为单位即时生效，而不是等半页填满。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-22\">二十二 · 压缩与复用：KV 不是只能原样存</h3>\n<p>KV 缓存的压缩有三条正交路径，在帧自回归里各有不同的适用面。第一条是精度压缩：把 K/V 从高精度降到 FP8 甚至更低，按每元素字节数直接缩小账本。风险在于时间维注意力的 K/V 参与的是跨帧一致性计算，量化误差会沿帧回灌放大——这与误差累积是同一类问题，压缩引入的偏差会被下一帧当作条件继续传播。因此精度压缩必须与帧间一致性监控联动，而不是一次性全局降精度。</p>\n<p>第二条是跨帧复用：相邻帧的时空注意力在时间维上高度重叠，历史帧的 K/V 在窗口内被反复读取。复用不是“少存”，而是“少算”——已缓存的 K/V 直接参与注意力，避免每帧重算全部历史，这正是单帧计算量不随展开时长线性增长的原因。但复用范围受窗口约束，窗口外的 K/V 被淘汰后若后续帧需要长程参考，只能重算或接受截断，这是固定窗口的固有代价。</p>\n<p>第三条是结构压缩：对时间维做低秩近似或对旧帧做池化摘要，把多帧 K/V 压成更少的代表向量。这条路径直接冲击长程记忆的保真度，在闭环驾驶里尤其危险——被压掉的可能是规划器真正关心的远处运动线索。工程判断是：结构压缩只应用于窗口中最旧的一段，且摘要必须保留可回溯的原始帧引用，以便一致性漂移被检出时回退。</p>\n<p>代价核算上，精度压缩省的是容量与带宽，跨帧复用省的是算力，结构压缩省的是容量但引入保真度风险。三者不能同时拉满：把 KV 压到极低精度又做激进结构压缩，时间维注意力的输入分布会偏离训练时的分布，帧间一致性下降，而这一下降在材料给出的信息里没有量化手段可核验，只能靠监控项兜底。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-23\">二十三 · 卸载与带宽：瓶颈到底在哪一层</h3>\n<p>当 KV 账超出 HBM3e 容量时，卸载到主机内存是唯一出路，但卸载把“容量问题”换成了“带宽问题”。Blackwell 的 HBM3e 提供的是片内高带宽，而主机侧链路（PCIe 或 Grace 侧的 NVLink-C2C）带宽低一个量级以上。KV 卸载若发生在每帧注意力的关键路径上，单帧时延会被链路带宽直接钉死：每帧要搬运的 KV 字节数除以链路带宽，就是不可压缩的传输下界。</p>\n<div class=\"formula\">$$T_{\\text{offload}} \\ge \\frac{S_{\\text{kv,miss}}}{BW_{\\text{link}}},\\qquad \\text{util} = \\frac{BW_{\\text{link}}\\cdot T_{\\text{frame}}}{S_{\\text{kv,miss}}}$$</div>\n<p>其中 $S_{\\text{kv,miss}}$ 是该帧注意力需要但不在 HBM 中的 KV 字节数。这个下界说明：卸载只应作用于窗口中最旧、访问频率最低的帧，且应做预取——在控制周期到来前把下一帧可能需要的旧页搬回 HBM，把传输藏在计算后面。若预取命中率不足，传输就暴露在关键路径上，帧时延抖动，闭环节奏被破坏。</p>\n<p>带宽瓶颈还有另一层：即便 KV 全在 HBM 内，时间维注意力的读带宽也是瓶颈。每帧注意力要读窗口内全部历史 K/V，读取量随窗口线性增长，而计算量因复用而不线性增长——这意味着窗口拉长时，系统从“算力受限”滑向“带宽受限”。判断当前受限类型的实用方法是看窗口加倍时单帧时延的增幅：若接近线性，说明带宽在读 K/V 上；若明显低于线性，说明复用生效、算力仍是主约束。这个判断不需要实验数字，只需要在调度器里记录窗口长度与帧时延的比值随时间的走势。</p>\n<p>具体例子：假设某路仿真窗口 16 帧、每帧 KV 20 MB 量级，则单帧时间维注意力需读约 320 MB 的 K/V；若 HBM 有效读带宽按 TB/s 量级，这部分读取在百微秒量级，尚可被计算掩盖；但若窗口拉到 64 帧，读取量到 1.3 GB 量级，读取时间进入毫秒量级，与少步采样的计算时间同量级，带宽开始成为可见瓶颈。此时继续拉长窗口换来的长程记忆，代价是帧时延的确定性下降——闭环控制最忌讳的正是时延不确定。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-24\">二十四 · 可复算的显存预算：从窗口与并发反推档位</h3>\n<p>把前面的账本收拢成一个可复算的预算流程，按以下顺序推进：先定单帧 KV 字节，再乘窗口得单路 KV，再乘并发得总 KV；然后估激活峰值乘并发；再加权重与工作区；最后与 HBM3e 容量比较，若超则按“降并发 → 缩窗口 → 降 KV 精度 → 卸载最旧页”的顺序退让。这个顺序的依据是代价不对称：降并发直接损失吞吐但不动模型行为；缩窗口损失长程记忆；降精度引入一致性风险；卸载引入时延抖动。越往后越伤闭环质量，所以调度器应优先在前两步内解决。</p>\n<table class=\"mini\">\n<thead><tr><th>账目</th><th>驱动变量</th><th>增长性质</th><th>退让手段</th></tr></thead>\n<tbody>\n<tr><td>权重</td><td>参数量、精度</td><td>静态常驻</td><td>换更低精度档位（需一致性验证）</td></tr>\n<tr><td>激活峰值</td><td>批大小、帧分辨率</td><td>瞬态、随批线性</td><td>降批、分块计算</td></tr>\n<tr><td>KV 缓存</td><td>窗口长度、并发路数</td><td>滚动、随两者乘积</td><td>缩窗口、分页池化、精度压缩、卸载</td></tr>\n<tr><td>工作区</td><td>通信缓冲、解码临时区</td><td>半静态</td><td>复用缓冲、限制并发通信组</td></tr>\n</tbody>\n</table>\n<p>一个可复算的算例：设单帧单层 KV 为 $d_{\\text{kv}}\\cdot 2\\cdot b_{\\text{kv}}$，取 $d_{\\text{kv}}=4096$、$b_{\\text{kv}}=1$ 字节（FP8 量级），则单层单帧约 8 KB；40 层即 320 KB/帧；窗口 16 帧约 5 MB/路——这个量级远小于前文按 20 MB 估的例子，说明 KV 账对“每层头维展开宽度”和“层数”极其敏感，配置差一倍，账本差数倍。因此预算不能拍脑袋，必须按实际模型的 $n_l$ 与 $d_{\\text{kv}}$ 代入。若并发 8 路、窗口 32 帧，KV 项到 40 MB×8 量级仍属轻量；真正吃显存的是激活峰值与权重，这也解释了为什么在 Blackwell 上 KV 压缩的收益常被高估——它省的是容量余量，不是峰值瓶颈。</p>\n<p>反过来，若模型层数与头维更大、KV 按 BF16 存、窗口拉到 64 帧、并发 16 路，KV 项会跃升到数 GB 量级，此时分页池化与精度压缩才真正进入收益区。预算流程的结论应是条件式的：先算清 $n_l\\cdot d_{\\text{kv}}\\cdot L_w\\cdot B$ 这个乘积落在哪个量级，再决定是否值得为 KV 引入分页内核的复杂度。对窗口短、并发低的部署，连续切片加简单淘汰更省工程成本；对长窗口、高并发的闭环仿真集群，分页与池化是必选项。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-25\">二十五 · 与批调度和 SLO 的耦合点</h3>\n<p>显存账本最终要落到调度决策上。FAR-Drive 的批调度在单帧时延与显存余量之间折中，超时请求降批或缩短窗口——这句话的工程含义是：显存余量是调度的输入，而不是事后报警。调度器应在每个控制周期开始时读取当前活跃页数、激活峰值预测与权重常驻量，算出“还能容纳几路、每路窗口能开多长”，再据此接纳新请求。若余量不足，优先缩短新请求的窗口而非拒绝，因为闭环仿真里“短记忆但按时出帧”比“长记忆但错过控制节拍”更有用。</p>\n<p>耦合的另一面是 SLO 的反向约束：单帧时延预算里包含采样计算、VAE 解码、KV 读取与可能的卸载传输。当窗口拉长导致 KV 读取进入时延预算的显著份额时，调度器必须把窗口长度当作时延变量而非仅显存变量——这正是带宽瓶颈与显存账本的交汇处。一个实用的工程判断是：为每路仿真维护“窗口长度—帧时延”的滑动估计，当该比值随窗口增长的斜率超过阈值时，停止拉长窗口，转而用结构压缩或摘要保留长程线索，把确定性时延守住。</p>\n<p>最后落在具体机制上：分页块表的淘汰策略应与批调度共用同一个页池水位信号——当水位越过高线，调度器先缩窗口释放整页，再考虑降精度；当水位回落到低线，才允许新请求以长窗口接入。这样显存账本、分页机制与 SLO 三者闭环，而不是各自为政地调参。</p>\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-26\">二十六 · 帧级到达流下的连续批处理：把“批”从请求改成节拍</h3>\n<p>FAR-Drive 的请求形态与常规 LLM 服务不同：一个闭环仿真会话不是“发一条 prompt 等一段视频”，而是按控制周期逐帧到达的指令流。每一帧的生成依赖上一帧的解码结果回灌，因此同一会话内部的帧是严格串行的；可并行的只有不同仿真会话之间的帧。这决定了调度器的最小调度单元不是“整段视频请求”，而是“某一会话在当前控制周期要出的那一帧”。连续批处理在这里的含义因此要改写：不是等一批请求凑齐再跑，而是在每个控制节拍上，把当前所有活跃会话的待生成帧动态拼成一个批，批内成员随会话的到达与结束而进出。</p>\n<p>机制上，调度器维护一张活跃会话表，每行记录该会话的滚动窗口长度、历史帧 KV 缓存句柄、已消耗的蒸馏步数进度与上一帧的解码完成时间。节拍到来时，凡上一帧已回灌完毕的会话进入候选集，按优先级取前 N 个拼批，N 由当前显存余量与单帧时延预算共同决定。批内各帧共享同一次时空注意力 kernel 启动，但各自持有独立的窗口 KV 视图。代价体现在两处：批越大，单帧的注意力计算被摊薄、SM 占用率上升，吞吐改善；但批越大，单帧完成时间也越长，因为同一批内最慢的成员决定整批的完成时刻，而闭环的下一节拍必须等整批回灌完毕才能推进。这就是吞吐与时延在此处的直接对立。</p>\n<p>设控制周期为 <span>T</span>，批内第 i 个会话的单帧计算时间为 <span>t_i(B)</span>（随批大小 B 单调增），则一个节拍内可推进的会话数受限于：</p>\n<div class=\"formula\">$$B^\\*=\\max\\Big\\{B:\\ \\max_{i\\le B} t_i(B)+t_{\\text{dec}}+t_{\\text{comm}}\\le T\\Big\\}$$</div>\n<p>其中 <span>t_dec</span> 是 VAE 解码时延，<span>t_comm</span> 是跨节点聚合开销。这个式子说明批大小不是自由参数，而是被最慢成员与解码尾巴夹住的上界。工程上的做法是把解码从关键路径上剥离（见第四节），否则 VAE 解码会以固定时延吃掉整个节拍余量。</p>\n<p>具体例子：NVL72 机架内跑多路城市路口仿真，每路会话的滚动窗口长度不同（拥堵场景窗口长、空旷场景窗口短）。若按统一批大小调度，长窗口会话会成为批内最慢成员，把短窗口会话一起拖过 SLO。正确做法是按窗口长度分桶拼批，桶内成员计算量接近，最慢成员与平均成员的差距被压小，批的完成时刻更可预测。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-27\">二十七 · Chunked prefill 的等价物：首帧冷启动与窗口重算的分块</h3>\n<p>FAR-Drive 里没有文本 prefill，但有它的结构等价物：会话首帧的冷启动，以及窗口淘汰后需要重建的历史条件编码。首帧时历史缓冲为空，条件只有初始观测与控制指令，计算量小；真正昂贵的是会话中途因窗口滑动而必须重算的那部分跨帧注意力——当最旧帧被淘汰、新帧进入窗口时，窗口内所有帧的相对位置索引发生变化，若缓存按绝对位置存储，就需要对窗口内剩余帧做一次重编码。这一步的代价随窗口长度线性增长，且发生在关键路径上，会造成周期性的时延尖峰。</p>\n<p>分块思路是把这次重编码切成若干小块，跨多个控制节拍摊销，而不是在单帧内一次做完。伪代码层面：</p>\n<ul>\n<li>窗口滑动触发时，标记窗口内需重编码的帧区间 [a, b)，按固定块大小 s 切分；</li>\n<li>每个节拍只处理一个块，块内帧的 KV 重算与当前帧的采样共享同一次 kernel 启动；</li>\n<li>未完成重编码的帧在注意力中沿用旧位置编码的近似值，标记为 stale，并在块完成后原子替换；</li>\n<li>若某节拍时延余量不足，跳过本块，把重编码推迟到负载低谷。</li>\n</ul>\n<p>代价是数值上的：stale 帧参与注意力时位置编码不精确，会引入帧间一致性的轻微偏差，这与自回归误差累积叠加，属于必须监控的漂移源。收益是尾延迟：把一次 O(窗口长度) 的尖峰摊成 O(s) 的平缓负载，P99 单帧时延显著收敛。工程判断是块大小 s 应取使单块计算时间不超过节拍余量一半的值，留出另一半给突发。</p>\n<p>具体例子：一个窗口长度为数十帧的会话在窗口满后每帧都触发滑动，若每帧同步重编码整个窗口，单帧时延会出现规律性尖峰，规划器在该节拍拿不到新帧只能沿用旧帧做动作评估，闭环控制质量下降。分块摊销后尖峰消失，代价是窗口边缘若干帧的位置编码短暂 stale。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-28\">二十八 · 优先级与抢占：谁先出帧，谁被降窗口</h3>\n<p>闭环驾驶的会话不是等价的。规划器正在评估的候选动作所在会话，其下一帧直接决定控制决策，优先级最高；后台批量回放的仿真会话优先级低。调度器需要两级优先级：会话级（决定批内排序）与帧级（决定同一会话内是否允许跳帧）。抢占在这里不是杀掉任务重跑，而是三种降级手段的组合：降批（把该会话移出当前批，下个节拍再试）、缩窗（临时缩短滚动窗口，减少注意力计算量与 KV 读取量）、降步（在蒸馏步数预算内取更少的采样步，牺牲帧质量换时延）。</p>\n<p>抢占的判定需要一个可比较的紧迫度度量。设会话 j 的截止时刻为 <span>d_j</span>（由控制周期与规划器调用时刻决定），当前时刻 <span>now</span>，预估单帧剩余工作量为 <span>w_j</span>，则紧迫度可取：</p>\n<div class=\"formula\">$$\\text{urg}_j=\\frac{w_j}{d_j-now},\\qquad \\text{抢占条件：}\\ \\text{urg}_j&gt;\\text{urg}_k\\ \\text{且}\\ \\text{余量不足}$$</div>\n<p>余量不足指当前批的预估完成时刻已超过某个高优先级会话的截止时刻。此时调度器把低紧迫度会话移出批，腾出的显存与 SM 时间给高紧迫度会话。代价是低优先级会话的帧率下降，其闭环仿真在时间上被拉长，但这在离线回放场景可接受；不可接受的是高优先级会话因批内混入长窗口成员而被拖过截止时刻，这正是尾延迟的主要来源。</p>\n<p>具体例子：一个路口仿真会话的规划器在每个控制周期要评估若干候选轨迹，每个候选对应一路生成请求，这些请求共享同一历史帧缓冲但条件指令不同。它们构成一个高优先级组，调度器应把它们拼成同质批（窗口相同、步数相同），避免与后台长窗口回放会话混批。混批会让候选评估的时延方差变大，规划器被迫在部分候选上使用过期帧，决策质量受损。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-29\">二十九 · 分离式预填/解码在帧自回归中的映射</h3>\n<p>分离式预填/解码的原始动机是把计算密集的 prefill 与访存密集的 decode 放到不同资源池，避免相互干扰。映射到 FAR-Drive：每帧的“预填”等价物是条件编码与窗口内跨帧注意力的 KV 重算（计算密集、可批处理），而“解码”等价物是 VAE 把潜变量还原为像素（访存密集、写历史缓冲、时延固定）。二者对资源的需求形态不同，混在同一关键路径上会让单帧时延被两者之和锁死。</p>\n<p>机制上可把 VAE 解码卸载到独立的解码池：采样侧只产出潜变量并写入一个潜变量队列，解码池按自己的批大小消费队列、解码、回灌历史缓冲。这样采样侧的批大小只受注意力计算与 KV 读取约束，不再被解码时延夹住；解码侧可以攒批提高 VAE 吞吐，因为解码不参与下一帧的条件构造（下一帧条件用的是潜变量历史，像素帧只供规划器与可视化）。代价是引入一次跨池传输与队列等待，若解码池积压，回灌延迟会反过来拖慢规划器的评估节奏。因此队列深度需要背压：当潜变量队列超过阈值，采样侧降批，把资源让给解码池。</p>\n<p>代价核算上，分离的收益是采样侧单帧时延的确定性提升与解码侧吞吐提升，成本是额外的显存（潜变量队列缓冲）与一次跨节点或跨进程通信。在 NVL72 内，跨池通信走 NVLink 5，带宽充足但延迟不可忽略；若解码池与采样池跨节点，通信开销必须计入节拍预算。工程判断是：当 VAE 解码时延占单帧预算的比例超过某个阈值时，分离才划算；比例低时，同池串行更简单且无通信开销。</p>\n<p>具体例子：高分辨率输出下 VAE 解码成为单帧预算的主要项，此时把解码池独立、采样侧专注少步流匹配，能让采样批大小提升、单帧采样时延下降，规划器拿到潜变量后即可先行评估（若规划器接受潜空间输入），像素解码异步完成供回放。这要求规划器与生成器的接口允许潜空间与像素空间解耦，属于系统设计层面的取舍。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-30\">三十 · 尾延迟的压法：从批内最慢成员到窗口长度的方差</h3>\n<p>尾延迟在帧自回归闭环里有三个独立来源，压法各不相同。第一是批内最慢成员：批的完成时刻由最大 <span>t_i</span> 决定，压法是同质分桶与按窗口长度排序拼批，让批内计算量方差最小。第二是窗口滑动的重编码尖峰：压法是第二节的分块摊销。第三是抢占引起的重排：被降批的会话在下个节拍重新进入候选集时，其历史缓冲已过期一个周期，条件构造需要额外的一致性校正，这会带来一次额外计算。压法是把降批会话标记为冷重入，给它的首帧分配更宽松的时延预算或更短的窗口，避免它在下一个节拍再次成为最慢成员。</p>\n<p>尾延迟与吞吐的取舍可以用一个简单的容量关系表达。设单帧平均计算量为 <span>c</span>，节拍为 <span>T</span>，批大小为 <span>B</span>，则理论会话吞吐为 <span>B/T</span> 帧每秒；但 P99 时延由 <span>max_i t_i(B)</span> 决定，而 <span>max_i t_i</span> 随 B 增长快于均值。因此存在一个吞吐拐点：继续增大 B，均值吞吐上升但 P99 越过节拍，有效吞吐（满足 SLO 的帧数）反而下降。调度器的目标不是最大化 B，而是把 B 停在 P99 恰好触及节拍的位置，并把方差来源逐个削平，使这个拐点右移。</p>\n<p>具体例子：多路仿真并发时，若不做同质分桶，批内窗口长度差异大，P99 由最长窗口会话决定，拐点出现在很小的 B 上，机架算力大量闲置。做分桶后批内方差下降，同样的 P99 约束下 B 可以更大，有效吞吐提升，代价是调度器需要维护更多小批、批启动开销增加。这是一个典型的“用调度复杂度换尾延迟”的工程判断。</p>\n<p>监控项应落在可归因的量上：单帧时延的 P50/P99 分离统计、批内计算量方差、窗口滑动重编码的触发频率与单次耗时、降批与缩窗的发生次数、潜变量队列深度。这些量共同决定闭环能否稳定跟上控制节拍；任何一个量的漂移都会先在尾延迟上显形，再传导到规划器的决策质量。</p>\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-31\">三十一 · 切分维度：帧自回归把并行问题改写</h3>\n<p>FAR-Drive 的并行拓扑不是先验选择，而是被帧自回归结构逼出来的。整段视频扩散可以在时间维做序列并行，把一段长序列摊到多卡上同时去噪；帧自回归则相反，第 t 帧必须等第 t−1 帧解码回灌后才能开工，时间维天然串行。于是可切分的只剩三处：帧内空间维（潜变量网格）、条件编码与历史 KV 缓存、以及批内多路闭环仿真。这三处分别对应 TP（张量并行，切帧内注意力的头与通道）、EP/DP（把不同仿真路或不同专家分到不同 rank）、以及一种受限的 PP（流水线并行，把 VAE 解码与下一帧的条件拼接错开一级）。时间维串行意味着流水线气泡无法靠增加 stage 消除，PP 的收益上限被单帧时延预算锁死。</p>\n<p>具体机制上，时空注意力在帧内空间维切分后，每个 rank 只持有部分 head 的 Q/K/V，跨帧时间维的 KV 缓存则按 head 切分冗余存放或按 rank 分片。设单帧注意力计算量为 $C_{\\text{attn}}$、参数量为 $W$，TP 度为 $N_t$，则每 rank 的计算与权重占用近似为：</p>\n<div class=\"formula\">$$C_{\\text{rank}}\\approx\\frac{C_{\\text{attn}}}{N_t}+C_{\\text{comm}}(N_t),\\qquad W_{\\text{rank}}\\approx\\frac{W}{N_t}$$</div>\n<p>代价在于 $C_{\\text{comm}}$ 随 $N_t$ 上升：每层注意力后要做 All-Reduce 归约部分和，TP 度越大，单次归约的参与者越多、单帧内归约次数不变但每次更贵。以 B200 NVL72 单机架为例，NVLink 5 把单 GPU 对外带宽抬到远高于 PCIe 的量级，NVSwitch 让机架内任意两 GPU 全互联，这才使 TP=8 甚至跨节点 TP 在帧时延预算内可行；若拓扑退化为 PCIe，同样的 TP 度会让归约时延吃掉单帧预算的可观份额。工程判断是：帧自回归下 TP 度应取到“归约时延 < 单帧预算的固定比例”为止，而不是盲目追高。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-32\">三十二 · All-Reduce 与 All-to-All：两种通信的不同代价曲线</h3>\n<p>TP 走 All-Reduce（或 Reduce-Scatter + All-Gather），EP 走 All-to-All，二者代价曲线形状不同，不能混为一谈。All-Reduce 的通信量正比于激活大小、与 TP 度弱相关（ring 实现下每 rank 收发约 $2(N_t-1)/N_t$ 倍激活），延迟随跳数增长；All-to-All 的通信量正比于 token 数乘以被路由到的专家数，且是**非对称、非均匀**的——不同 rank 发出的 token 数取决于路由分布，最慢的那条链路决定整体时延。</p>\n<p>对 FAR-Drive 而言，EP 的用武之地不在生成器主干（帧自回归的时空注意力没有天然的专家稀疏性），而在条件编码侧：若把控制指令编码、历史帧特征提取、VAE 解码拆成不同功能模块并分派到不同 rank 组，模块间的激活搬运就是一次 All-to-All 形态的传输。伪代码思路：</p>\n<ul>\n<li>帧 t 到达 → rank 组 A 编码指令与历史窗口 → All-to-All 把条件张量按目标模块分片发给组 B；</li>\n<li>组 B 做少步流匹配采样 → All-to-All 把潜变量发给组 C 做 VAE 解码；</li>\n<li>组 C 解码写回历史缓冲 → 下一控制周期重复。</li>\n</ul>\n<p>系统代价：All-to-All 的尾延迟由最大分片决定，若某路仿真的历史窗口特别长、条件张量偏大，它会拖慢整批。缓解手段是按窗口长度做负载均衡分片，或在窗口超阈值时降批。吞吐上，All-to-All 的带宽利用率通常低于 All-Reduce 的规整模式，NVSwitch 的全互联能削掉跨组跳数，但削不掉分片不均带来的尾延迟。例子：批内 8 路仿真，其中 2 路窗口已满、6 路窗口半满，条件张量大小差一倍，All-to-All 的实际完成时间由那 2 路决定，等效吞吐下降。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-33\">三十三 · NIXL 传输：把 KV 缓存搬出计算路径</h3>\n<p>历史帧 KV 缓存复用是 FAR-Drive 压单帧计算量的核心机制，但它同时制造了一个传输问题：缓存要跨帧、跨 rank、甚至跨节点存活。NIXL 的价值在于把 KV 缓存的搬运从计算 rank 的同步路径上剥离——用异步、点对点的传输把远端 KV 分片拉进本地，或把淘汰帧的缓存写回低速层，使计算流不被阻塞。对帧自回归，这等价于把“读历史 KV”变成一次可重叠的预取：在帧 t−1 解码的同时预取帧 t 所需窗口的远端分片。</p>\n<p>代价模型可以写成单帧时延的分解：</p>\n<div class=\"formula\">$$T_{\\text{frame}}=T_{\\text{sample}}+T_{\\text{decode}}+T_{\\text{comm}}^{\\text{hidden}}+\\max\\big(0,\\,T_{\\text{prefetch}}-T_{\\text{decode}}\\big)$$</div>\n<p>只要预取时延被解码时延覆盖，KV 传输就不进关键路径；一旦窗口跨节点、远端分片多，$T_{\\text{prefetch}}$ 超过 $T_{\\text{decode}}$，关键路径被拉长。NVLink 5 + NVSwitch 让机架内 KV 搬运的带宽远高于跨机架以太网，因此窗口应尽量约束在单机架内，跨机架只在窗口极长时才值得。显存侧，NIXL 允许把淘汰帧的 KV 下沉到远端显存池而非直接丢弃，缓解固定窗口的记忆截断，但下沉本身消耗带宽与远端显存，需与窗口长度一起核算。例子：窗口 16 帧、TP=8 时每 rank 持有的 KV 分片若全部本地，预取为零；一旦部分分片在邻节点，每帧多一次 NIXL 拉取，其带宽占用与帧率直接挂钩。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-34\">三十四 · 通信何时成为瓶颈：三个判据</h3>\n<p>不是所有并行都值得。判断通信是否成为瓶颈，看三条曲线是否交叉。第一，**计算通信比**：单帧计算时间 $T_{\\text{comp}}$ 与单帧通信时间 $T_{\\text{comm}}$ 之比，若 $T_{\\text{comm}}/T_{\\text{comp}}&gt;1$，加并行度只会更慢。第二，**批内方差**：All-to-All 与窗口长度耦合，批内各路仿真窗口不齐时，尾延迟决定吞吐，方差越大越不该用 EP 形态的切分。第三，**SLO 余量**：闭环控制周期给出单帧时延上限，若通信已占预算的显著比例，任何抖动都会击穿 SLO，此时应降并行度、缩窗口、降批，而不是加卡。</p>\n<table class=\"mini\"><thead><tr><th>切分</th><th>通信原语</th><th>随度增长的代价</th><th>FAR-Drive 适用处</th></tr></thead><tbody><tr><td>TP</td><td>All-Reduce</td><td>归约跳数与参与者线性增</td><td>帧内空间维注意力、head 切分</td></tr><tr><td>EP</td><td>All-to-All</td><td>分片不均导致尾延迟</td><td>条件编码/解码模块间搬运</td></tr><tr><td>PP</td><td>点对点</td><td>气泡受时间维串行锁死</td><td>解码与条件拼接错开一级</td></tr><tr><td>DP</td><td>无（或参数广播）</td><td>显存复制、无梯度同步</td><td>多路闭环仿真各占一份</td></tr></tbody></table>\n<p>具体例子：TP=8 时每层注意力后一次 All-Reduce，单帧若有 L 层则 L 次归约；把 TP 提到 16 而单帧计算只减半、归约参与者翻倍，$T_{\\text{comm}}$ 的增长快于 $T_{\\text{comp}}$ 的下降，净时延变差。反过来，DP 把不同仿真路分到不同 rank，通信几乎为零，代价是每 rank 各持一份权重与独立窗口，显存翻倍——在显存余量充足时这是最省通信的选择。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-35\">三十五 · 与批调度、窗口长度的耦合</h3>\n<p>并行切分不是独立变量，它与前文写过的批调度、滚动窗口互相咬合。批大小上升会放大 All-to-All 的分片规模与方差，也会抬高每帧激活的通信量；窗口长度上升会抬高 KV 缓存的传输量与显存水位。三者共同约束单帧时延，可写成一条容量约束：给定控制周期 $T_{\\text{ctrl}}$、单帧预算占比 $\\rho$，则</p>\n<div class=\"formula\">$$\\text{batch}\\times\\big(T_{\\text{sample}}+T_{\\text{decode}}+T_{\\text{comm}}\\big)\\le \\rho\\cdot T_{\\text{ctrl}}\\cdot N_{\\text{rank}}$$</div>\n<p>工程上按此式反解批大小：先固定 TP 度与窗口长度，实测 $T_{\\text{comm}}$ 随批大小的斜率，再取满足约束的最大批。超时请求的处理顺序应是先缩窗口（直接减 KV 传输与注意力计算）、再降批、最后才降 TP 度——因为降 TP 度会改变权重分片布局，触发重配置，代价远高于前两者。NVLink 5 与 NVSwitch 的意义正在于此：它们把 $T_{\\text{comm}}$ 的斜率压平，使约束式右端的可用预算更多留给采样与解码，而不是被归约吃掉。对 B200/GB200 NVL72 机架，机架内全互联让 TP 与 EP 的通信代价在机架尺度内可控，跨机架则需重新核算，这也是窗口与批应优先约束在单机架内的工程理由。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-36\">三十六 · 并行切分与通信：帧自回归闭环里，哪条链路先撞墙</h3>\n<p>FAR-Drive 的并行拓扑不是从训练继承下来的静态配置，而是被帧级滚动窗口的形状反向约束出来的。单帧条件由历史帧潜变量与控制指令拼接，时空注意力在帧内空间维与跨帧时间维分别切分：空间维切分适合 TP，因为每帧潜变量的空间块可以独立投影，但跨帧时间维的注意力要求每个 rank 看到窗口内全部帧的 KV 头，于是 TP 组内必须对 KV 缓存做复制或按头切分，复制意味着显存随 TP 度线性膨胀，按头切分则把 All-Reduce 引入每帧采样回路。PP 在这里的收益被窗口长度压制——把采样步切成 stage 会让每帧的激活在 stage 间往返，而帧时延预算以控制周期为单位，流水线气泡直接吃掉闭环节奏；只有当批内并发路数足够多、stage 能被多路请求填满时 PP 才成立。EP 与 DP 的分工更直接：DP 承载多路仿真并发，每路独立滚动窗口、互不通信；EP 只在把 VAE 解码或时空注意力拆成专家块时出现，代价是每帧一次 All-to-All，其通信量正比于窗口内帧数与潜变量通道数。</p>\n<div class=\"formula\">$$T_{\\text{frame}} \\approx \\underbrace{K\\cdot T_{\\text{sample}}}_{\\text{少步流匹配}} + \\underbrace{T_{\\text{dec}}}_{\\text{VAE 解码}} + \\underbrace{\\sum_{l}\\big(T_{\\text{AR},l}+T_{\\text{A2A},l}\\big)}_{\\text{并行通信}}$$</div>\n<p>把上式拆开看，通信什么时候成为瓶颈就有了判据：当 <em>K·T_sample</em> 被步数蒸馏压到很小、而窗口内帧数增长使 All-to-All 的字节数随窗口线性上升时，通信项在单帧预算中的占比会反超采样项。NVLink 5 与 NVSwitch 提供的是机柜内高带宽全互联，All-Reduce 在 TP 组内是带宽受限而非延迟受限，真正昂贵的是跨节点 All-to-All——EP 切分一旦跨 NVL72 域，NIXL 的点对点传输就把每帧的专家激活搬运变成显存带宽与网卡队列的竞争。工程判断是：优先把 EP 组约束在单 NVSwitch 域内，让 All-to-All 走 NVLink；跨域只保留 DP 的请求分发与 KV 窗口的冷数据搬运，用 NIXL 异步预取下一窗口的历史帧潜变量，避免在采样关键路径上同步等待。</p>\n<table class=\"mini\"><thead><tr><th>切分</th><th>每帧通信形态</th><th>失效条件</th><th>系统代价</th></tr></thead><tbody><tr><td>TP</td><td>KV 头切分后 All-Reduce</td><td>窗口长、头数少，复制显存超水位</td><td>显存随 TP 度膨胀或每帧同步开销</td></tr><tr><td>EP</td><td>每帧 All-to-All</td><td>专家块跨 NVSwitch 域</td><td>字节数随窗口帧数线性增长</td></tr><tr><td>PP</td><td>stage 间激活传递</td><td>并发路数不足以填满流水</td><td>气泡直接侵占控制周期预算</td></tr><tr><td>DP</td><td>无组内通信</td><td>批大小受显存余量约束</td><td>窗口淘汰频率上升，长程记忆截断</td></tr></tbody></table>\n<p>通信瓶颈的第二个来源是 KV 缓存的滚动语义。历史帧 KV 复用使单帧计算量不随展开时长线性增长，但缓存本身要在 rank 间保持一致：TP 组内若按头切分，每帧新写入的 KV 只落在对应 rank，窗口淘汰最旧帧时各 rank 必须同步释放，否则显存水位漂移会让批调度误判余量。这里的代价不是带宽而是同步频率——每控制周期一次窗口推进，等于每帧一次轻量栅栏，栅栏延迟乘以并发路数后可能超过单帧采样本身。缓解手段是把窗口推进与批调度解耦：按若干帧为粒度批量淘汰，用 NIXL 在后台把即将淘汰的帧潜变量归档，前台只做指针切换。至于误差沿帧回灌累积，它与并行切分正交但会放大通信代价——帧间一致性下降时，规划器可能要求重生成，重生成意味着同一窗口内重复 All-to-All，此时瓶颈从带宽转为请求放大后的队列拥塞。</p>\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-37\">三十七 · 精度塌陷：从“少步轨迹”到“帧间漂移”的链式放大</h3>\n<p>FAR-Drive 的精度失败不是单帧画质问题，而是回灌结构决定的链式放大。每帧潜变量经 <span>Sample</span> 采样后立即 VAE 解码写回历史缓冲，下一帧条件直接取自这个解码结果，于是第 t 帧的采样偏差成为第 t+1 帧的输入条件。步数蒸馏把每帧采样压到少量步，少步轨迹与多步教师轨迹的偏差在单帧上或许可接受，但闭环把它变成一阶自回归误差传播：偏差不是被平均掉，而是被逐帧继承并叠加。</p>\n<div class=\"formula\">$$\\epsilon_{t+1}=\\mathcal{F}\\big(\\epsilon_{t},\\,\\mathbf{c}_{t+1}\\big)+\\delta_{t+1},\\qquad \\|\\epsilon_{t}\\|\\lesssim \\sum_{k=1}^{t}\\|\\delta_{k}\\|\\cdot\\prod_{j=k}^{t-1}\\|\\partial\\mathcal{F}/\\partial\\mathbf{z}_{j}\\|$$</div>\n<p>工程上要监控的不是单帧 PSNR，而是<strong>帧间一致性漂移率</strong>：对相邻帧在重叠区域做光流残差、对同一控制指令下的多路仿真做条件一致性比对、对历史缓冲中窗口首帧与当前帧做特征距离跟踪。这三项指标一旦出现单调上升，就说明少步蒸馏的偏差正在被闭环放大，而不是偶发噪声。定位手段是把窗口内每帧的采样步数与教师轨迹做离线重放比对，找出偏差首次超过阈值的帧号，再判断是蒸馏步数不足还是条件拼接处（历史潜变量与控制指令拼接）的数值精度问题。代价上，精度塌陷不会直接触发 OOM 或超时，属于静默降级，因此必须靠指标而非告警发现；一旦漂移率越线，回滚动作是提高该路仿真的采样步数或缩短窗口，用计算换一致性，单帧时延随之上升，需与 SLO 余量对齐后再执行。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-38\">三十八 · OOM 与显存水位：窗口长度与并发路数的乘积约束</h3>\n<p>显存占用由滚动窗口长度与批内并发路数共同决定，这是 FAR-Drive 最容易踩的容量陷阱。历史帧 KV 缓存按窗口保留，窗口满后淘汰最旧帧，因此单路仿真的 KV 显存近似正比于窗口长度；批内并发 N 路时，总占用近似为 N 倍窗口 KV 加当前帧采样与 VAE 解码的瞬时峰值。OOM 往往不是稳态越界，而是<strong>瞬时峰值叠加</strong>：多路请求在同一控制周期同时到达，批调度把批大小推高，解码阶段的激活峰值与 KV 缓存同时驻留，触发分配失败。</p>\n<div class=\"formula\">$$M_{\\text{peak}}\\approx N\\cdot L_{\\text{win}}\\cdot M_{\\text{KV/frame}}+M_{\\text{sample}}+M_{\\text{decode}},\\qquad N\\le\\Big\\lfloor\\frac{M_{\\text{budget}}-M_{\\text{sample}}-M_{\\text{decode}}}{L_{\\text{win}}\\cdot M_{\\text{KV/frame}}}\\Big\\rfloor$$</div>\n<p>监控要分三层：进程级显存水位、按路拆分的 KV 缓存占用、以及解码阶段的瞬时峰值采样。定位时先看 OOM 发生在采样前还是解码后——前者多为批大小越界，后者多为解码激活峰值未被预算。具体例子：某路仿真窗口长度被配置得偏长以保留长程记忆，单路稳态占用尚可，但批内并发升到调度上限时总占用越过预算，表现为周期性 OOM 而非随机失败。回滚动作是先把批大小降到由上式反解的安全值，再按需缩短窗口；若业务不允许缩短窗口，则改为分块重叠策略，把窗口外历史以低秩摘要替代全量 KV，用一致性换显存。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-39\">三十九 · 批抖动：控制节拍与批大小耦合下的时延方差</h3>\n<p>闭环请求按控制节拍逐帧到达，批调度在单帧时延与显存余量之间折中，超时请求降批或缩短窗口。这套机制在负载平稳时表现良好，但一旦到达率出现抖动，批大小随之震荡，单帧时延方差被放大——这就是批抖动。根因是批大小既是吞吐杠杆又是时延杠杆：批越大，单帧计算被摊薄但排队时延上升；批越小，时延下降但 GPU 利用率塌陷，吞吐掉得比时延收益更快。</p>\n<p>诊断批抖动要看两个序列：每控制周期的实际批大小，以及该批内各请求的端到端时延分位。若批大小在相邻周期之间反复跳变、且时延 P99 与批大小呈滞后相关，说明调度器在时延与显存两个约束间来回切换策略。具体例子：多路仿真并发时，某几路请求因窗口较长占用显存多，调度器为腾出余量压低批大小，导致其余短窗口请求也被拖慢，形成“长窗口请求绑架全局批”的抖动。缓解机制是<strong>按窗口长度分组调度</strong>：把长窗口与短窗口请求分到不同批，各自按组内显存余量定批大小，避免单一约束绑架全局；同时给降批动作加滞回窗口，防止批大小在阈值附近震荡。代价是分组降低了批的混合度，短窗口组的利用率略降，但时延方差收敛，闭环节拍更稳。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-40\">四十 · 尾延迟：解码与采样预算的叠加点</h3>\n<p>单帧时延 SLO 匹配控制周期，尾延迟的来源不是平均采样成本，而是<strong>预算叠加点的最坏情况</strong>：采样步数、KV 缓存读取、VAE 解码三段串行，任一段出现长尾都会把整帧推出控制周期。KV 缓存读取的长尾来自窗口淘汰瞬间的缓存重排；解码的长尾来自分辨率与批内并发同时偏高时的激活峰值。少步蒸馏压低了采样段，但解码段并未被蒸馏，它在单帧预算中的占比随分辨率上升而变大。</p>\n<p>监控应把单帧时延拆成三段分别打点，而不是只看端到端。定位尾延迟时，先看 P99 落在哪一段：若落在解码段且与批大小正相关，说明解码激活峰值未被批调度纳入约束；若落在 KV 读取段且与窗口淘汰频率同步，说明淘汰策略触发了同步重排。具体例子：窗口满后每帧都淘汰最旧帧，若淘汰与读取在同一批次内串行执行，P99 会出现与窗口长度同周期的尖峰。回滚动作是把淘汰改为异步预淘汰、在控制周期空闲窗口内完成缓存整理，或对超时请求直接缩短窗口而非降批——后者牺牲长程记忆但保住节拍，前者保住记忆但增加显存整理开销，二者需按业务对一致性的容忍度取舍。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-41\">四十一 · 静默降级：没有告警的失败最贵</h3>\n<p>FAR-Drive 最危险的失败模式是静默降级：系统不 OOM、不超时、不报错，但生成质量在闭环中缓慢劣化。三条路径都会导致它——少步蒸馏偏差沿帧累积、窗口截断使长程条件丢失、缓存复用范围过大使旧帧 KV 与当前条件失配。三者都不触发资源告警，只表现为规划器评估动作后果时依据的视频逐渐偏离真实动力学。</p>\n<p>监控必须建立<strong>质量哨兵</strong>：在每路仿真中周期性插入一段以已知初始观测为条件的重放比对，把当前生成帧与离线多步教师轨迹做特征距离；同时跟踪窗口首帧与当前帧的条件一致性，以及缓存命中帧的年龄分布。一旦哨兵指标越线，定位顺序是先查缓存年龄分布（是否复用了过旧 KV）、再查窗口淘汰频率（是否截断过频）、最后查蒸馏步数与教师轨迹偏差。回滚策略分两级：一级是提高该路仿真的采样步数并缩小缓存复用范围，用计算换一致性；二级是重置该路历史缓冲、以当前观测重新起滚，代价是丢失长程记忆但切断误差传播链。具体判断依据是哨兵指标的斜率——若漂移率单调上升且与缓存年龄正相关，优先缩复用范围；若漂移在窗口淘汰后突跳，优先缩短窗口或改分块重叠。</p>\n<p>工程上要把这三类指标与资源指标放在同一监控面板上联动：显存水位、批大小、三段时延分位、漂移率、缓存年龄分布。单看资源指标只能发现 OOM 与超时，单看质量指标无法归因到调度或缓存决策；只有联动才能把“静默降级”还原成具体的机制失效点，并在 SLO 余量内选择回滚级别，而不是等到规划器在仿真中给出错误动作评估才被动发现。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-42\">四十二 · 失效链诊断：从精度塌陷到静默降级的可观测断点</h3>\n<p>帧自回归的失败很少以单点崩溃的形式出现，而是沿“条件—采样—解码—回灌”这条链逐级劣化。最典型的是精度塌陷：每帧解码结果回灌为下一帧条件，早期帧的偏差被当作事实输入，误差沿时间传播并逐帧放大；少步蒸馏进一步压缩了采样轨迹的纠偏余量，使偏差缺少在多步迭代中被修正的机会。诊断上应把“帧间一致性漂移”作为一等指标，而非只看单帧画质——在滚动窗口内对相邻帧的潜变量做差分能量统计，若该能量随展开时长单调上升而指令输入并未变化，即可判定为回灌污染而非指令响应。系统代价在于：漂移一旦发生，规划器评估的是被污染的动作后果，闭环决策随之偏移，而这种偏移不会触发任何显存或时延告警，属于典型的静默降级。</p>\n<p>第二类断点是显存与批抖动。显存占用由滚动窗口长度与批内并发路数共同决定，窗口满后淘汰最旧帧，但淘汰本身并不立即释放被 KV 缓存占用的分块，若分块重叠策略未与淘汰节奏对齐，显存水位会呈锯齿状抬升。批抖动则来自调度器在单帧时延与显存余量之间的折中：某路仿真超时触发降批或缩短窗口，窗口一变，历史条件长度随之改变，后续帧的注意力形状与缓存命中率全部重算，形成“降批—重算—再超时”的正反馈。定位手段是把窗口长度、批大小、淘汰频率三者与单帧时延画在同一时间轴上，若时延尖峰总是滞后于窗口淘汰事件一个控制周期，则瓶颈在缓存回收而非采样算力。尾延迟的根因往往不在均值：少数请求因窗口刚满、恰逢淘汰与解码并发而出现长尾，容量规划必须按尾部分位而非均值配置并发路数。</p>\n<div class=\"formula\">$$\\mathrm{SLO}_{\\text{frame}}:\\quad T_{\\text{sample}}(K)+T_{\\text{dec}}+T_{\\text{cache}} \\le T_{\\text{ctrl}},\\qquad W_{\\max}=\\Big\\lfloor \\frac{M_{\\text{budget}}-M_{\\text{act}}}{B\\cdot m_{\\text{kv}}} \\Big\\rfloor$$</div>\n<p>上式给出两个可操作的诊断边界：单帧预算由采样步数 K、解码与缓存读写三段构成，任一段超支都会击穿控制周期；窗口上限则由显存预算、批内路数 B 与每帧 KV 占用共同决定。工程上应把 K 与 W 作为可回滚的两个旋钮——精度塌陷时优先增大 K 或缩短窗口以恢复纠偏余量，OOM 与批抖动时优先降 B 或缩 W，而不是同时调整导致归因困难。回滚策略需版本化：蒸馏步数、窗口长度、量化档位三者应绑定为同一配置快照，任一指标越界即整体回退到上一快照，避免只回滚单项造成条件分布与缓存布局不匹配。监控项至少覆盖单帧时延分位、显存水位斜率、窗口淘汰频率、帧间一致性漂移与解码吞吐，其中漂移指标必须独立于时延指标告警，否则静默降级会被高吞吐掩盖。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>可观测断点</th><th>首选回滚旋钮</th></tr></thead><tbody><tr><td>精度塌陷</td><td>帧间潜变量差分能量单调上升</td><td>增大 K / 缩短 W</td></tr><tr><td>OOM</td><td>显存水位锯齿抬升、淘汰后不回落</td><td>降 B / 对齐分块回收</td></tr><tr><td>批抖动</td><td>时延尖峰滞后淘汰事件一周期</td><td>固定 W 后再调 B</td></tr><tr><td>尾延迟</td><td>淘汰与解码并发窗口内的长尾</td><td>按尾部分位限并发</td></tr></tbody></table>\n<p>最后一类边界是“把帧自回归当作整段扩散的滑窗推理”这一认知性失效：滑窗推理每帧独立重算历史，误差不跨帧回灌，而帧自回归的闭环特性使缓存复用与回灌互为因果——缓存省下的算力恰恰以窗口外历史被截断为代价，截断又削弱了长程一致性对漂移的约束。因此诊断不能只问“这一帧对不对”，而要问“这一帧的条件里有多少来自被截断窗口之外的记忆”。当窗口淘汰频率接近控制频率时，系统已退化为近似无记忆的逐帧生成，此时任何时延优化都只是在掩盖一致性损失；判断依据是淘汰频率与漂移指标是否同向上升，若是，则应停止压窗口、转向分离式预填解码或精度档位调整来换取记忆长度。</p>\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-43\">四十三 · 口径先立：这份材料能支撑什么读法</h3>\n<p>FAR-Drive 的公开材料只给出机制骨架，没有给出数据集、基线、硬件档位与任何定量结果。这意味着本部分的任务不是“读一张表”，而是先把口径立起来：哪些量在材料里被定义为工程变量，哪些量根本没有被定义。材料明确把采样步数、KV 缓存与滚动窗口列为“一等工程变量”，把单帧时延 SLO 与批大小、窗口长度写成耦合关系，并反复声明分辨率、解码吞吐、显存峰值、并行拓扑、量化方案均未给出。因此任何“帧率提升多少倍”“显存降到多少 GB”的说法都不具备可核验性，只能作为待测假设存在。读者在工程侧要做的第一件事，是把评测表拆成两栏：左栏是机制可推导的定性结论，右栏是必须自测才能填的数字。左栏可以写“单帧计算量不随展开时长线性增长”，右栏必须留空，等实测填入。</p>\n<p>与之配套的是一个最小可比的评测单元定义。闭环生成的一次“请求”不是一段视频，而是一个控制周期上的一帧：条件为窗口内历史帧潜变量与控制指令的拼接，输出为一帧像素并回灌。于是评测的最小粒度是“帧时延”，而不是“整段视频耗时”。把整段离线去噪的指标直接搬到帧自回归上，是口径错位的第一种形态——整段生成的吞吐按秒每视频计，帧自回归必须按毫秒每帧计，并且要与控制周期对齐。</p>\n<div class=\"formula\">$$\\mathrm{SLO}_{\\text{frame}}:\\quad T_{\\text{sample}}(K)+T_{\\text{decode}}+T_{\\text{cond}}\\;\\le\\;\\Delta t_{\\text{ctrl}}$$</div>\n<p>式中 $K$ 为蒸馏后的每帧采样步数，$T_{\\text{sample}}$ 为少步流匹配采样耗时，$T_{\\text{decode}}$ 为 VAE 解码耗时，$T_{\\text{cond}}$ 为条件拼接与 KV 缓存读取耗时，$\\Delta t_{\\text{ctrl}}$ 为控制周期。材料未给出这四项的任何数值，但公式本身给出了评测表的行结构：任何一份 FAR-Drive 的基准报告，若只报端到端帧率而不拆这四项，就无法判断瓶颈落在采样、解码还是条件组装上，也就无法与别的实现做可比对照。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-44\">四十四 · 硬件档位：材料未给，但档位决定窗口与批的可行域</h3>\n<p>材料明确写“硬件档位材料未给出，需按显存带宽与帧时延实测选定”。这句话在工程上不是免责声明，而是把硬件档位变成了评测的自变量。在 Blackwell 上，SM100/SM103 的显存档位（B200/B300 与 GB200/GB300 NVL72 的差异）直接决定两件事：滚动窗口能开多长，批内能并发几路仿真。显存占用由窗口长度与并发路数共同决定，窗口满后淘汰最旧帧，因此窗口长度是一个显存预算下的硬约束，而不是可随意调大的超参。窗口越长，历史 KV 缓存越大，单帧条件组装要读的缓存也越多；窗口越短，长程记忆被截断，帧间一致性下降。</p>\n<p>这里有一个可推导的显存账：设每帧潜变量的 KV 缓存占用为 $m_{\\text{kv}}$，窗口长度为 $W$，并发路数为 $B$，则缓存侧显存约为 $B\\cdot W\\cdot m_{\\text{kv}}$，再加上每路的活动潜变量、VAE 解码中间激活与模型权重。材料未给 $m_{\\text{kv}}$ 的具体值，但结构上可以看出：$B$ 与 $W$ 在显存上是乘性关系，降批与缩窗是两种等价的显存腾挪手段，而材料正是把“超时请求降批或缩短窗口”写成调度策略。这意味着评测时必须同时报 $(B, W)$ 二元组，只报批大小或只报窗口长度的结果不可比——同一帧时延可以在大 $B$ 小 $W$ 与小 $B$ 大 $W$ 两种配置下取得，但两者的帧间一致性与长程记忆质量完全不同。</p>\n<p>硬件档位还影响精度路径的选择。材料写“量化方案与硬件档位材料未给出”，而 NVFP4/FP8 在 Blackwell 上的可用性与收益取决于具体 SKU 的 tensor core 形态与显存带宽。工程判断是：在未给定量结果的前提下，精度档位应作为评测矩阵的一维显式记录（BF16 / FP8 / NVFP4），否则同一实现换精度后的帧时延差异会被误读为算法改进。功耗维度材料完全未提，闭环车载场景下功耗与散热是持续流式输出的实际约束，评测表应留一列待补全，而不是用“未提及”掩盖。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-45\">四十五 · batch 与并发：帧时延与显存余量的折中面</h3>\n<p>材料把批调度写成“按帧时延与显存余量调度批大小，超时请求降批或缩短窗口”。这是一个双约束调度问题：批越大，单帧的矩阵乘利用率越高、吞吐越好，但每路都要占一份窗口 KV 缓存与解码激活，显存余量下降；批越小，单帧时延更可控，但硬件利用率低。关键点在于帧自回归的批与传统 LLM 连续批处理不同——每一路的“序列”是沿时间滚动的帧，批内各路的历史窗口长度可以不同，因此批的构成是动态的，且每帧都要做一次条件组装与一次解码。</p>\n<p>可推导的伪代码思路如下：每个控制周期到来时，收集所有待生成路，按剩余显存余量与各路当前窗口长度排序，优先纳入窗口短、显存占用低的路以填满批；若某路预计单帧时延超过 $\\Delta t_{\\text{ctrl}}$，则对该路降批（单独成批）或缩短其窗口。这里没有给出具体阈值，但机制上说明了一件事：批大小不是固定超参，而是随显存水位与帧时延反馈动态变化的量。评测时必须报告批大小的分布或调度策略，而不是一个静态数字。</p>\n<ul>\n<li>具体机制：窗口满后淘汰最旧帧，淘汰频率是显存水位与窗口长度的函数；材料把“窗口淘汰频率”列为监控项，说明它是可观测的运行指标。</li>\n<li>系统代价：批内并发路数增加会线性抬高缓存侧显存，同时抬高单帧条件组装的缓存读取带宽；材料未给带宽数字，但结构上这是并发的主要代价。</li>\n<li>具体例子：多路闭环仿真并发时，若某路因指令突变需要更长历史以保持一致性，调度器面临“扩窗还是降批”的选择；材料给出的策略是超时即降批或缩窗，即优先保时延、牺牲记忆长度。</li>\n</ul>\n<p>需要强调的是，材料未给出任何吞吐数字，因此“批大小调到多少最优”无法从材料推出。工程上应把批调度视为一个需要在线实测的控制环：以单帧时延与显存水位为反馈信号，而不是以离线跑出的固定批大小为配置。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-46\">四十六 · 指标怎么读：TTFT/TPOT 在帧自回归里的重新定义</h3>\n<p>把 LLM 推理的 TTFT/TPOT 直接套到帧自回归上会产生语义漂移。在 FAR-Drive 的机制里，首帧的“首 token 时间”对应的是闭环启动时历史缓冲为空、以初始观测与控制指令为条件生成第一帧的时延；此后每个控制周期的“token”是一整帧，帧间间隔才是真正的节奏指标。材料写“闭环开始时历史缓冲为空，首帧以控制指令与初始观测为条件”，这意味着首帧没有 KV 缓存可复用，条件组装与采样都要从零开始，其时延结构与稳态帧不同。评测表若把首帧时延与稳态帧时延混为一个平均值，会掩盖冷启动代价。</p>\n<div class=\"formula\">$$\\mathrm{TPOT}_{\\text{frame}}\\;\\equiv\\;\\frac{1}{N}\\sum_{t=1}^{N}\\big(T_{\\text{sample},t}+T_{\\text{decode},t}+T_{\\text{cond},t}\\big)$$</div>\n<p>稳态帧间间隔的均值如上式，$N$ 为观测的帧数。材料未给 $N$ 与任何分项数值，但公式指出了读法：帧间间隔的方差比均值更能反映闭环稳定性，因为控制周期是硬节拍，偶发的长尾帧会直接造成超时降批。材料把“单帧时延、显存水位、窗口淘汰频率与帧间一致性漂移”列为监控项，其中帧间一致性漂移是视频生成特有的指标，LLM 的 TPOT 口径里没有对应物。读一份 FAR-Drive 的基准报告时，应检查它是否把一致性漂移与帧时延分开报告：若只报时延不报漂移，就无法判断少步蒸馏是否以一致性换时延。</p>\n<p>吞吐的口径同样要重定义。整段视频生成的吞吐按“视频每秒”计，帧自回归的吞吐应按“帧每秒每路”与“总帧每秒”两个层次分别报告，后者受批内并发路数影响。材料未给吞吐数字，因此任何跨实现的吞吐对比都必须同时声明 $(B, W, K, \\text{精度档位})$ 四元组，缺一项即不可比。功耗维度材料未提，车载闭环场景下持续流式输出的功耗是容量规划的实际约束，评测表应显式留空待测。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-47\">四十七 · 哪些提升不可比：四类常见的口径错位</h3>\n<p>第一类是把帧自回归与整段离线去噪对比。整段生成可以一次性去噪全部帧、全局共享注意力，帧自回归则每帧只对窗口内帧计算、历史 KV 从缓存读取。两者在计算图结构上不同，前者的“每视频耗时”与后者的“每帧时延”不是同一量纲，直接相除得到的“加速比”没有意义。材料明确写“把视频生成从整段离线去噪改为帧自回归”，这一改写本身改变了评测单元，任何跨范式的倍数对比都应被拒绝。</p>\n<p>第二类是把不同 $(B, W)$ 配置下的帧时延直接对比。如前所述，$B$ 与 $W$ 在显存上是乘性关系，同一帧时延可由不同配置取得，而配置差异直接改变帧间一致性与长程记忆。材料把窗口长度写成显存档位下的硬约束，因此跨配置对比必须固定 $(B, W)$，否则测得的差异里混入了记忆长度这一混杂变量。</p>\n<p>第三类是把不同蒸馏步数 $K$ 下的结果对比。材料写“每帧采样步数经步数蒸馏压到少量步”，但未给具体步数。$K$ 是闭环时延的主要来源，$K$ 越小帧时延越低，但少步蒸馏对帧间一致性的影响缺少实验数据支撑。因此报“帧时延降低”时必须同时报 $K$，否则无法区分是蒸馏更激进还是缓存复用更有效。</p>\n<p>第四类是把不同精度档位的结果对比。材料未给量化方案，BF16 与 FP8/NVFP4 的帧时延差异会被误读为算法改进。工程判断是：精度档位必须作为评测矩阵的显式一维，且在同一档位内比较。</p>\n<table class=\"mini\"><thead><tr><th>对比维度</th><th>可比条件</th><th>不可比的典型形态</th></tr></thead><tbody><tr><td>生成范式</td><td>同为帧自回归</td><td>帧时延 vs 整段每视频耗时</td></tr><tr><td>并发与窗口</td><td>固定 $(B, W)$</td><td>大 $B$ 小 $W$ vs 小 $B$ 大 $W$ 混比</td></tr><tr><td>采样预算</td><td>固定 $K$</td><td>不同蒸馏步数下比帧时延</td></tr><tr><td>精度档位</td><td>同档位内比较</td><td>BF16 vs FP8 混比</td></tr></tbody></table>\n<p>这张表的用法是：拿到任何一份 FAR-Drive 的基准数字，先按四行逐项核对可比条件，任一项不满足即标记为不可比，而不是把数字放进同一张柱状图。材料未给出定量结果这一事实，恰恰说明这张表目前只能用于“拒绝不可比声明”，而不能用于“确认可比提升”。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-48\">四十八 · 误差累积与窗口截断：评测必须携带的两个负向指标</h3>\n<p>材料把“自回归误差累积”与“固定滚动窗口导致的长程记忆截断”列为主要局限，并明确写“材料未给出长时闭环下的漂移量化与缓解手段”。这意味着任何一份合格的 FAR-Drive 评测，除了正向的帧时延与吞吐，必须携带两个负向指标：帧间一致性漂移随展开时长的增长曲线，以及窗口长度 $W$ 变化对长程记忆质量的影响。前者对应误差沿帧回灌传播，后者对应窗口外历史被截断。</p>\n<p>可推导的读法是：漂移曲线应按展开帧数 $t$ 绘制，而不是按视频秒数，因为误差传播的自变量是回灌次数。若某实现报告“长时闭环质量稳定”，必须给出 $t$ 的范围与 $W$ 的取值；材料未给这些数字，因此此类声明目前不可核验。窗口截断的评测则应做 $W$ 的扫描：固定 $B$ 与 $K$，改变 $W$，观察帧间一致性与单帧时延的权衡曲线。材料把窗口淘汰频率列为监控项，说明 $W$ 是可运行时调整的量，扫描 $W$ 是可行的实验设计。</p>\n<p>工程判断落在最后这一点上：FAR-Drive 的评测口径不是“跑出一个帧率”，而是“在 $(B, W, K, \\text{精度})$ 四元组下同时报告帧时延分项、一致性漂移与窗口截断效应”。材料未给硬件档位与任何定量结果，因此当前可做的只有机制性结论的确认与不可比声明的拒绝；真正的数字必须由读者在自己的 Blackwell 档位上按上述四元组实测填入，且每一项都要与 $\\Delta t_{\\text{ctrl}}$ 的硬节拍对齐，否则闭环调度器拿到的反馈信号本身就是失真的。</p>\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-49\">四十九 · 迁移到非驾驶视频域：条件接口与回灌语义先改</h3>\n<p>FAR-Drive 的骨架由三件事咬合而成：帧级自回归单元、条件拼接（历史帧潜变量 + 控制指令）、采样后立即解码回灌。迁到别的领域，最先崩的不是算子而是条件接口。驾驶域的控制指令是低维、逐周期到达、语义稳定的向量；换成文本引导的视频生成，条件变成高维、稀疏、跨帧不变的嵌入序列，若仍按“每帧拼一次指令”的方式组织，条件编码会被重复计算 N 次，单帧预算被无谓放大。正确做法是把不变条件预编码为一份 KV，随滚动窗口一起缓存，只让变化部分（历史帧潜变量）进入每帧的拼接。反过来，迁到机器人操作视频或具身仿真，条件里多了本体状态与动作序列，动作是高频离散 token，拼接前需做时间对齐与降采样，否则条件张量的时间维会迅速超过历史帧窗口，把时空注意力的切分比例压垮。</p>\n<p>回灌语义同样要重写。驾驶闭环里“生成即评估”，帧写入缓冲后立刻被规划器消费，因此解码必须同步、低时延。迁到离线内容生产，回灌可以异步化：解码与下一帧采样流水线重叠，用双缓冲交换，单帧时延让位于吞吐。这是一次明确的取舍——闭环要求 <span class=\"formula\">$$T_{\\text{frame}} = T_{\\text{sample}}(K) + T_{\\text{decode}} \\le T_{\\text{control}}$$</span> 成立，而离线场景只要求 <span class=\"formula\">$$\\text{Throughput} = \\frac{B}{T_{\\text{sample}}(K)+T_{\\text{decode}}}$$</span> 最大化，两者对批大小与窗口长度的最优解方向相反。工程判断：凡是有外部消费者按固定节拍读取最新帧的场景，解码不可异步；凡是消费者按批拉取的场景，异步解码几乎必然划算。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-50\">五十 · 迁到纯扩散/流匹配主干：蒸馏与缓存的耦合会松掉</h3>\n<p>FAR-Drive 的单帧预算主要来自步数蒸馏，蒸馏把少步轨迹拉向多步教师轨迹。这套机制迁到没有蒸馏前身的模型上要付额外代价：教师轨迹本身要在线或离线产出，蒸馏目标依赖教师采样路径的稳定性。若目标模型是纯扩散（非流匹配），少步采样的轨迹曲率更大，同样步数下逼近误差更高，帧间一致性下降会比驾驶域更明显——驾驶帧的空间结构受车道、车辆几何约束，误差有物理先验兜底；开放域视频没有这层兜底，漂移会直接表现为纹理闪烁与物体形变。</p>\n<p>KV 缓存复用的收益也会变形。FAR-Drive 的缓存复用建立在“历史帧潜变量在窗口内不变”这一前提上，时空注意力只对窗口内帧计算。迁到高动态场景（快速镜头运动、剧烈光照变化），旧帧 KV 与当前帧条件的相关性衰减更快，复用带来的近似误差上升，等效于用一致性换时延。此时应把缓存复用范围从“全窗口”收缩为“最近若干帧 + 关键帧锚点”，锚点帧的 KV 定期重算，代价是每 N 帧出现一次计算尖峰，需要调度层预留显存与算力余量吸收。伪代码层面的判断是：</p>\n<div class=\"formula\">$$\\text{reuse}(t)=\\begin{cases}\\text{cache hit}, &amp; t-t_{\\text{anchor}} &lt; W_{\\text{hot}}\\\\ \\text{recompute}, &amp; \\text{otherwise}\\end{cases}$$</div>\n<p>其中 <span class=\"formula\">$$W_{\\text{hot}}$$</span> 由场景动态程度标定，而非固定等于滚动窗口长度。这是迁移时必须改的一个参数，不改就是把驾驶域的静态先验硬套到动态域。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-51\">五十一 · 不适用边界：长程一致性与强指令耦合场景</h3>\n<p>固定滚动窗口截断长程历史，这是该方案的结构性边界，不是调参能绕过的。任何要求“第 t 帧与第 t−1000 帧保持同一身份/同一场景布局”的任务——长视频叙事、角色一致性生成、长时驾驶场景回放——都会撞上窗口截断。KV 缓存只保留窗口内帧，窗口外信息在淘汰瞬间丢失，回灌链上的误差无法被远端历史纠正。缓解手段只有两类：把关键帧摘要压缩成低维记忆向量注入条件（增加条件编码开销），或分层生成（先低频关键帧再插值，破坏帧级自回归的流式性）。两者都偏离了原方案的“单帧独立预算”假设，属于换架构而非调参。</p>\n<p>强指令耦合场景同样不适用。闭环驾驶的控制指令是“建议性”的，生成器有一定自由度；若迁到指令必须被精确执行的场景（如按精确轨迹渲染、按精确动作序列生成），条件到输出的映射需要可验证的保真度，而少步蒸馏 + 缓存复用本质是近似采样，无法给出逐帧的指令遵循保证。此时单帧时延预算要让位于保真度，蒸馏步数必须上调，闭环节奏随之失守。工程判断：这套方案的适用域是“指令宽松、时延刚性、历史相关性随时间衰减”的三元组；三者缺一，迁移就要重估采样预算。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-52\">五十二 · 规模上限：窗口、批与显存的三角约束</h3>\n<p>规模上限不在单卡算力，而在显存水位与窗口长度的乘积关系。显存占用近似为 <span class=\"formula\">$$M \\approx B \\cdot \\big(W \\cdot S_{\\text{kv}} + S_{\\text{act}} + S_{\\text{vae}}\\big)$$</span>，其中 <span class=\"formula\">$$W$$</span> 是滚动窗口帧数，<span class=\"formula\">$$S_{\\text{kv}}$$</span> 是单帧 KV 字节数，<span class=\"formula\">$$B$$</span> 是并发仿真路数。三者中任意两个固定，第三个就被钉死。驾驶域可以靠缩短窗口换并发路数，因为控制周期短、历史相关性衰减快；迁到需要长窗口的域，<span class=\"formula\">$$W$$</span> 上升直接压缩 <span class=\"formula\">$$B$$</span>，吞吐按比例下降。这不是线性外推能掩盖的：窗口翻倍、并发减半，端到端吞吐不变但单帧时延因批变小而恶化，SLO 反而更难满足。</p>\n<p>量化是唯一能在不改窗口的前提下松绑显存的手段，但 NVFP4/FP8 对 KV 缓存的适用性取决于注意力的数值敏感度。历史帧 KV 被反复读取复用，量化误差会在每次复用中累积放大，等效于给回灌链再加一层漂移源。可接受的工程路径是：当前帧条件与查询保持高精度，历史 KV 用低精度存储、读取时按需反量化，把误差限制在“旧帧近似”而非“当前帧计算”上。代价是反量化带来额外带宽开销，与缓存复用省下的带宽部分对冲。规模上限的实质判断是：当 <span class=\"formula\">$$W \\cdot S_{\\text{kv}}$$</span> 超过单卡显存的可分配份额时，方案必须转向跨卡分窗口或分层记忆，此时并行与通信开销进入预算，帧级自回归的“单帧独立”假设失效。</p>\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-53\">五十三 · 迁移检查清单与判断落点</h3>\n<p>把方案搬到新模型/新领域，按以下顺序核对，任一项不成立就要改架构而非调参：</p>\n<ul>\n<li>条件是否逐帧变化？不变条件必须预编码缓存，否则条件编码重复计算吃掉单帧预算。</li>\n<li>消费者是否按固定节拍读取？是则解码同步、回灌阻塞；否则解码可异步流水。</li>\n<li>历史相关性衰减速度是否与窗口长度匹配？不匹配则缓存复用范围要收缩并设锚点重算。</li>\n<li>任务是否要求跨窗口长程一致性？要求则固定窗口方案不适用，需引入记忆向量或分层生成。</li>\n<li>指令保真度是否有硬约束？有则少步蒸馏的近似采样不可接受，时延预算让位。</li>\n<li>显存三角（窗口 × 并发 × 单帧 KV）是否有可行解？无解则必须跨卡分窗口，接受通信开销。</li>\n</ul>\n<p>最后落在具体机制上：这套方案的可迁移内核不是“帧自回归”这个形式，而是“把采样步数、KV 复用范围、滚动窗口长度三个量当作联立约束求解”的工程姿态。迁到新域时，先测历史帧 KV 与当前帧条件的相关性衰减曲线，用这条曲线定 <span class=\"formula\">$$W_{\\text{hot}}$$</span> 与锚点间隔，再反推窗口长度与批大小的可行域；相关性衰减快的域，窗口可以短、并发可以高，方案几乎原样可用；衰减慢的域，窗口被迫拉长，显存三角立刻收紧，此时任何“调大 batch 提吞吐”的口号都是错的，正确动作是承认规模上限并转向分层或跨卡。</p>\n\n\n<h3 id=\"paper-far-drive-frame-autoregressive-video-2026-sec-54\">五十四 · 迁移边界：帧自回归推理骨架在何处成立、何处失效</h3>\n<p>这套方案的迁移性来自一个很窄的机制内核：以历史帧潜变量与控制指令拼接为条件、每帧少量蒸馏步采样、解码后立即回灌、窗口内 KV 复用。它成立的前提是“条件信号短、控制节拍固定、误差可被窗口截断吸收”。迁到别的模型时，最先要改的不是采样器而是条件编码器——若目标模型的条件是长文本提示、音频片段或跨模态检索向量，拼接式条件构造会破坏其原有注意力布局，必须改为独立的 cross-attention 条件流，并把 KV 缓存从“历史帧自缓存”扩展为“条件缓存 + 历史帧缓存”两段式，缓存管理复杂度与显存水位随之上升。迁到别的领域时，判断标准是控制周期与生成时延的比值：设单帧预算为 <span class=\"formula-inline\">$$T_{\\text{frame}} = K\\cdot t_{\\text{step}} + t_{\\text{dec}} + t_{\\text{cache}}$$</span>，其中 <span class=\"formula-inline\">$$K$$</span> 为蒸馏步数、<span class=\"formula-inline\">$$t_{\\text{dec}}$$</span> 为 VAE 解码时延、<span class=\"formula-inline\">$$t_{\\text{cache}}$$</span> 为缓存读写与窗口淘汰开销。当控制周期显著大于 <span class=\"formula-inline\">$$T_{\\text{frame}}$$</span>（如离线渲染、批量素材生成），帧自回归的流式优势消失，反而因逐帧解码与缓存维护引入额外开销，此时整段去噪或分块并行更划算；当控制周期逼近甚至小于 <span class=\"formula-inline\">$$T_{\\text{frame}}$$</span>，方案才真正被逼到必须压缩 <span class=\"formula-inline\">$$K$$</span> 与窗口长度，代价是帧间一致性下降。</p>\n<p>失效条件集中在三处。其一是误差回灌：每帧解码结果写入缓冲并成为下一帧条件，早期偏差沿时间传播，而固定窗口只截断历史、不纠正已污染的条件分布，长时闭环下漂移无上界约束；迁到长镜头、慢变化场景时该问题被放大，迁到高频切换、强指令驱动的场景时反而被新指令不断“重置”，这也是该骨架更适合短周期闭环而非长视频生成的根本原因。其二是窗口截断：窗口长度 <span class=\"formula-inline\">$$W$$</span> 同时决定显存与长程记忆，显存占用近似随 <span class=\"formula-inline\">$$W$$</span> 与批内并发路数 <span class=\"formula-inline\">$$B$$</span> 线性增长，即 <span class=\"formula-inline\">$$M \\approx B\\cdot(W\\cdot m_{\\text{kv}} + m_{\\text{dec}})$$</span>，缩短窗口换时延等于用一致性换吞吐，这一折中在多路仿真并发时会被批调度放大。其三是蒸馏步数的下限：少步采样使轨迹逼近教师轨迹，但步数压到极小时，帧内细节与跨帧纹理连续性同时退化，且该退化在闭环中表现为规划器评估的动作后果失真，而非单纯的画质下降。</p>\n<table class=\"mini\"><thead><tr><th>迁移目标</th><th>必须改动的部件</th><th>主要系统代价</th><th>适用判断</th></tr></thead><tbody><tr><td>同类视频扩散模型、控制节拍不变</td><td>条件编码器、KV 缓存分段</td><td>缓存显存上升，单帧时延略增</td><td>可直接迁移，先实测 <span class=\"formula-inline\">$$T_{\\text{frame}}$$</span></td></tr><tr><td>长文本/多模态条件生成</td><td>cross-attention 条件流、缓存管理</td><td>条件缓存占用带宽，批大小受限</td><td>需重构条件路径，不宜照搬拼接式条件</td></tr><tr><td>离线批量视频生成</td><td>无需帧回灌，改分块并行</td><td>逐帧解码与缓存维护成为纯开销</td><td>不适用，流式骨架失去意义</td></tr><tr><td>高帧率、强指令闭环</td><td>进一步压 <span class=\"formula-inline\">$$K$$</span>、缩窗口</td><td>一致性下降，漂移风险上升</td><td>可用但须监控帧间漂移</td></tr></tbody></table>\n<p>规模上限不在模型参数量，而在“窗口 × 并发 × 步数”三者构成的时延-显存联合约束。单卡上，窗口长度与批内并发路数共同挤压显存余量，超时请求只能降批或缩短窗口，这两条路径都直接损伤闭环质量；跨卡扩展时，历史帧 KV 缓存若按张量并行切分，跨帧时间维的注意力会引入额外通信，通信开销随窗口增长而累积，使“单帧计算量不随展开时长线性增长”的机制优势被通信项抵消。工程判断是：该方案适合控制周期明确、条件信号短、可接受窗口截断的闭环仿真场景；迁到开放式长视频生成或条件极长的多模态生成时，应把帧自回归降级为分块生成加后处理一致性校正，而不是强行把窗口拉长——拉长窗口换来的记忆，代价是显存水位与批吞吐同时失守，且误差回灌问题并未因此缓解。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 155\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"69.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">FAR-Drive: </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Frame-AutoRegressive Video</text><text x=\"292.0\" y=\"95.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\"> G…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"82.5\" x2=\"271.0\" y2=\"82.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 78.0 L 270.0 87.0 L 278.0 82.5 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"82.5\" x2=\"515.0\" y2=\"82.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 78.0 L 514.0 87.0 L 522.0 82.5 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"145.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2026 · arXiv preprint</text></svg><figcaption><b>家谱</b> · FAR-Drive: Frame-AutoRe… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>材料未给出具体数据集名称</td></tr><tr><td>基线</td><td>材料未给出对比基线</td></tr><tr><td>主要结果</td><td>材料未给出定量结果；可确认的机制性结论是帧自回归把生成组织为流式滚动，配合…</td></tr><tr><td>消融</td><td>材料未给出消融实验；按机制推断应考察蒸馏步数、历史窗口长度与 KV 缓存复…</td></tr><tr><td>局限</td><td>材料未给出实验规模与硬件档位；主要限制在于自回归误差累积、固定滚动窗口导致…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-far-drive-frame-autoregressive-video-2026 · 共 9 个片段</p>\n";break;}}})();
